                    author={suggestion.author}
                    label={suggestion.author}
                  />
                </span>
                <button
                  type="button"
                  onClick$={props.onClose$}
                  class="persona-note__tool focus-ring"
                  aria-label="Close proposed edit"
                  title="Close — decide later"
                >
                  <CloseIcon />
                </button>
              </div>
            </div>

            <div class="persona-note__scroll">
