// Shared by every ink pass. Prepended to each module at pipeline build time.

fn hash21(p: vec2f) -> f32 {
  var q = fract(p * vec2f(123.34, 456.21));
  q += dot(q, q + 45.32);
  return fract(q.x * q.y);
}

fn hash22(p: vec2f) -> vec2f {
  let n = hash21(p);
  return vec2f(n, hash21(p + n + 17.17));
}

// Smooth value noise on a lattice that wraps every `period` cells, so the
// fiber sheet tiles without a seam.
fn tiledNoise(p: vec2f, period: f32) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = hash21(i - period * floor(i / period));
  let b = hash21((i + vec2f(1.0, 0.0)) - period * floor((i + vec2f(1.0, 0.0)) / period));
  let c = hash21((i + vec2f(0.0, 1.0)) - period * floor((i + vec2f(0.0, 1.0)) / period));
  let d = hash21((i + vec2f(1.0, 1.0)) - period * floor((i + vec2f(1.0, 1.0)) / period));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn segmentDistance(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
  return length(pa - ba * h);
}

// Single-constant Kubelka–Munk: pigment absorbs and scatters, so layering
// darkens the way ink on paper does instead of greying like alpha.
fn kmAbsorption(r: vec3f) -> vec3f {
  let c = clamp(r, vec3f(0.002), vec3f(0.998));
  return (1.0 - c) * (1.0 - c) / (2.0 * c);
}

fn kmReflectance(ks: vec3f) -> vec3f {
  return 1.0 + ks - sqrt(ks * ks + 2.0 * ks);
}

// Lays the paper's fibers once per device: a tiling sheet the ink runs along.
//   r  fiber density, where capillaries pull water fastest
//   gb grain direction of the strongest strand, packed to 0..1
//   a  sizing, the slow blotchy variation in how thirsty the sheet is

struct FiberParams {
  size: u32,
  cell: f32,
  grainAngle: f32,
  grainSpread: f32,
}

@group(0) @binding(0) var sheet: texture_storage_2d<rgba8unorm, write>;
@group(0) @binding(1) var<uniform> params: FiberParams;

const STRANDS_PER_CELL: i32 = 3;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) id: vec3u) {
  if (id.x >= params.size || id.y >= params.size) {
    return;
  }
  let p = vec2f(id.xy) + 0.5;
  let cells = f32(params.size) / params.cell;
  let home = floor(p / params.cell);

  var density = 0.0;
  var strongest = 0.0;
  var direction = vec2f(cos(params.grainAngle), sin(params.grainAngle));

  for (var oy = -2; oy <= 2; oy++) {
    for (var ox = -2; ox <= 2; ox++) {
      let cell = home + vec2f(f32(ox), f32(oy));
      let wrapped = cell - cells * floor(cell / cells);
      for (var s = 0; s < STRANDS_PER_CELL; s++) {
        let seed = wrapped * 7.31 + f32(s) * 13.7;
        let h = hash22(seed);
        let k = hash22(seed + 3.1);
        let center = (cell + h) * params.cell;
        let angle = params.grainAngle + (k.x - 0.5) * params.grainSpread;
        let dir = vec2f(cos(angle), sin(angle));
        let halfLength = mix(6.0, 22.0, k.y);
        let width = mix(0.55, 1.5, hash21(seed + 9.4));
        let d = segmentDistance(p, center - dir * halfLength, center + dir * halfLength);
        let strand = exp(-d * d / (width * width)) * mix(0.45, 1.0, h.y);
        density += strand;
        if (strand > strongest) {
          strongest = strand;
          direction = dir;
        }
      }
    }
  }

  let period = f32(params.size) / 64.0;
  let pulp = tiledNoise(p / 64.0, period) * 0.6 + tiledNoise(p / 9.0, f32(params.size) / 9.0) * 0.4;
  let sizing = tiledNoise(p / 96.0 + 11.0, f32(params.size) / 96.0);
  let fibers = clamp(density * 0.55 + pulp * 0.35, 0.0, 1.0);

  textureStore(sheet, vec2i(id.xy), vec4f(fibers, direction * 0.5 + 0.5, sizing));
}

