// One step of wet ink on paper. Each cell holds
//   x water standing in the sheet
//   y pigment still suspended in that water
//   z pigment that has settled into the fibers
//   w how far a wet front has passed, for revealing what lies beneath
//
// Water moves cell to cell by capillarity, quicker along the grain. Pigment
// rides the water a little behind it. Edges dry first, so the wet interior
// keeps feeding them and carries pigment outward: the dark rim of a dried
// blot. Every flux is the same seen from either side, so ink is conserved.

struct SimParams {
  width: u32,
  height: u32,
  fiberOffsetX: u32,
  fiberOffsetY: u32,
  flow: f32,
  anisotropy: f32,
  absorb: f32,
  evaporation: f32,
  edgeRing: f32,
  fade: f32,
  pin: f32,
  revealAt: f32,
  dropCount: u32,
  splatScale: f32,
  fiberScale: f32,
  carry: f32,
}

struct Drop {
  a: vec2f,
  b: vec2f,
  radius: f32,
  water: f32,
  pigment: f32,
  ragged: f32,
}

@group(0) @binding(0) var src: texture_2d<f32>;
@group(0) @binding(1) var dst: texture_storage_2d<rgba16float, write>;
@group(0) @binding(2) var fibers: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: SimParams;
@group(0) @binding(4) var<storage, read> drops: array<Drop>;
@group(0) @binding(5) var<storage, read_write> splat: array<atomic<u32>>;

const NEIGHBORS = array<vec2i, 8>(
  vec2i(-1, -1), vec2i(0, -1), vec2i(1, -1),
  vec2i(-1, 0), vec2i(1, 0),
  vec2i(-1, 1), vec2i(0, 1), vec2i(1, 1),
);

// density, grain direction (-1..1), sizing
fn fiberAt(c: vec2i) -> vec4f {
  let size = vec2i(textureDimensions(fibers));
  let q = vec2i(floor(vec2f(c) * params.fiberScale)) + vec2i(i32(params.fiberOffsetX), i32(params.fiberOffsetY));
  let f = textureLoad(fibers, ((q % size) + size) % size, 0);
  return vec4f(f.r, f.gb * 2.0 - 1.0, f.a);
}

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) id: vec3u) {
  let dims = vec2i(i32(params.width), i32(params.height));
  let c = vec2i(id.xy);
  if (c.x >= dims.x || c.y >= dims.y) {
    return;
  }
  let s = textureLoad(src, c, 0);
  let here = fiberAt(c);
  var water = s.x;
  var pigment = s.y;
  var settled = s.z;
  var revealed = s.w;

  var waterIn = 0.0;
  var pigmentIn = 0.0;
  var around = 0.0;
  var count = 0.0;
  for (var k = 0; k < 8; k++) {
    let o = NEIGHBORS[k];
    let n = c + o;
    if (any(n < vec2i(0)) || any(n >= dims)) {
      continue;
    }
    let other = textureLoad(src, n, 0);
    let there = fiberAt(n);
    let len = length(vec2f(o));
    let toward = vec2f(o) / len;
    let along = 0.5 * (abs(dot(here.yz, toward)) + abs(dot(there.yz, toward)));
    let capillary = 0.35 + 0.325 * (here.x + there.x);
    let conductance = capillary * mix(1.0, along * along * 1.6, params.anisotropy) / len;
    // A thin film stays pinned where it is; only standing water travels.
    let mobile = smoothstep(params.pin, params.pin * 3.0, max(water, other.x));
    let flux = params.flow * conductance * mobile * (other.x - water);
    let concentration = select(
      pigment / max(water, 1e-4),
      other.y / max(other.x, 1e-4),
      flux > 0.0,
    );
    waterIn += flux;
    pigmentIn += flux * min(concentration, 4.0) * params.carry;
    around += other.x;
    count += 1.0;
  }
  water = max(water + waterIn, 0.0);
  pigment = max(pigment + pigmentIn, 0.0);

  for (var k = 0u; k < params.dropCount; k++) {
    let drop = drops[k];
    let reach = drop.radius * (1.0 + drop.ragged * (here.x - 0.5));
    let dist = segmentDistance(vec2f(c) + 0.5, drop.a, drop.b);
    let wetted = 1.0 - smoothstep(reach * 0.55, reach, dist);
    water += drop.water * wetted;
    pigment += drop.pigment * wetted;
  }

  // Splatter that came down since the last step.
  let landed = f32(atomicExchange(&splat[u32(c.y) * params.width + u32(c.x)], 0u)) * params.splatScale;
  water += landed * 1.5;
  pigment += landed;

  let meanAround = around / max(count, 1.0);
  let rim = clamp(1.0 - meanAround / max(water, 1e-4), 0.0, 1.0);
  let thirst = mix(0.6, 1.4, here.w);
  let evaporated = min(water, params.evaporation * thirst * (1.0 + params.edgeRing * rim));
  let drying = select(0.0, evaporated / water, water > 1e-5);
  let deposit = min(pigment, pigment * drying + pigment * params.absorb * here.x);
  water -= evaporated;
  pigment -= deposit;
  settled += deposit;

  // Once dry, the stain eases back into the page.
  let dryness = 1.0 - smoothstep(0.0, params.pin, water);
  settled = max(settled - settled * params.fade * dryness, 0.0);

  revealed = max(revealed, smoothstep(params.revealAt * 0.4, params.revealAt, water + settled));
  textureStore(dst, c, vec4f(min(water, 4.0), min(pigment, 4.0), min(settled, 4.0), revealed));
}

// Droplets thrown when a stamp comes down. Each flies outward, falls, and
// lands into the shared splat grid, which the next sim step soaks up.

struct Droplet {
  pos: vec2f,
  vel: vec2f,
  height: f32,
  rise: f32,
  mass: f32,
  alive: f32,
}

struct SplatterParams {
  width: u32,
  height: u32,
  count: u32,
  gravity: f32,
  drag: f32,
  _pad0: f32,
  _pad1: f32,
  _pad2: f32,
}

@group(0) @binding(0) var<storage, read_write> droplets: array<Droplet>;
@group(0) @binding(1) var<storage, read_write> splat: array<atomic<u32>>;
@group(0) @binding(2) var<uniform> params: SplatterParams;

const MASS_UNITS: f32 = 1024.0;

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) id: vec3u) {
  if (id.x >= params.count) {
    return;
  }
  var d = droplets[id.x];
  if (d.alive < 0.5) {
    return;
  }
  d.pos += d.vel;
  d.vel *= params.drag;
  d.height += d.rise;
  d.rise -= params.gravity;
  if (d.height <= 0.0) {
    let cell = vec2i(floor(d.pos));
    if (all(cell >= vec2i(0)) && cell.x < i32(params.width) && cell.y < i32(params.height)) {
      atomicAdd(&splat[u32(cell.y) * params.width + u32(cell.x)], u32(d.mass * MASS_UNITS));
    }
    d.alive = 0.0;
  }
  droplets[id.x] = d;
}

