// Composites the wet field onto the page. The canvas sits under real text,
// so it only ever paints paper, wetness, and pigment.

struct RenderParams {
  paper: vec3f,
  strength: f32,
  ink: vec3f,
  sheen: f32,
  cover: vec3f,
  revealing: f32,
  texel: vec2f,
  fiberScale: vec2f,
  fiberOffset: vec2f,
  dark: f32,
  grain: f32,
}

@group(0) @binding(0) var field: texture_2d<f32>;
@group(0) @binding(1) var fieldSampler: sampler;
@group(0) @binding(2) var fibers: texture_2d<f32>;
@group(0) @binding(3) var fiberSampler: sampler;
@group(0) @binding(4) var<uniform> params: RenderParams;

struct VertexOut {
  @builtin(position) position: vec4f,
  @location(0) uv: vec2f,
}

@vertex
fn vs(@builtin(vertex_index) i: u32) -> VertexOut {
  let corner = vec2f(f32((i << 1u) & 2u), f32(i & 2u));
  var out: VertexOut;
  out.position = vec4f(corner * 2.0 - 1.0, 0.0, 1.0);
  out.uv = vec2f(corner.x, 1.0 - corner.y);
  return out;
}

// On a dark sheet the ink is the light colour, so mix in the inverted space
// where the pigment still reads as absorbing.
fn pigmentOver(base: vec3f, ink: vec3f, amount: f32) -> vec3f {
  if (params.dark > 0.5) {
    let ks = kmAbsorption(1.0 - base) + kmAbsorption(1.0 - ink) * amount;
    return 1.0 - kmReflectance(ks);
  }
  let ks = kmAbsorption(base) + kmAbsorption(ink) * amount;
  return kmReflectance(ks);
}

@fragment
fn fs(in: VertexOut) -> @location(0) vec4f {
  let s = textureSample(field, fieldSampler, in.uv);
  let fiber = textureSample(fibers, fiberSampler, in.uv * params.fiberScale + params.fiberOffset);
  let tooth = mix(1.0 - params.grain, 1.0 + params.grain, fiber.r);

  let water = s.x;
  let pigment = (s.y * 0.65 + s.z) * tooth * params.strength;
  let wet = smoothstep(0.0, 0.6, water) * params.sheen;

  // Under the stain: the cover (when revealing) or the page itself.
  let cover = 1.0 - s.w;
  let showCover = params.revealing * cover;
  let ground = mix(params.paper, params.cover, showCover);

  // Wet paper loses the air between its fibers and darkens.
  let soaked = mix(ground, ground * select(0.86, 1.14, params.dark > 0.5), wet);
  var color = pigmentOver(soaked, params.ink, pigment);

  // A thin specular glint off standing water, lit from the upper left.
  let dx = textureSample(field, fieldSampler, in.uv + vec2f(params.texel.x, 0.0)).x
    - textureSample(field, fieldSampler, in.uv - vec2f(params.texel.x, 0.0)).x;
  let dy = textureSample(field, fieldSampler, in.uv + vec2f(0.0, params.texel.y)).x
    - textureSample(field, fieldSampler, in.uv - vec2f(0.0, params.texel.y)).x;
  let normal = normalize(vec3f(-dx * 3.0, -dy * 3.0, 1.0));
  let glint = pow(max(dot(normal, normalize(vec3f(-0.45, -0.55, 1.0))), 0.0), 40.0);
  color += vec3f(glint * wet * 0.12);

  let marked = clamp(pigment * 6.0 + wet * 0.9, 0.0, 1.0);
  let alpha = max(showCover, marked * 0.94);
  if (alpha <= 0.002) {
    return vec4f(0.0);
  }
  // Composite the mark over whatever ground shows, then premultiply.
  let shown = mix(params.paper, color, select(marked, 1.0, showCover > 0.0));
  return vec4f(toSrgb(shown) * alpha, alpha);
}

