/**
 * How a sheet of ink behaves. Every surface runs the same simulation; a
 * preset only changes how wet, how thirsty, and how long it stays.
 */
export interface InkTuning {
  /** CSS pixels per simulation cell. Smaller is finer and costs more. */
  cellPx: number;
  /** Capillary speed between cells. Above ~0.2 the step goes unstable. */
  flow: number;
  /** 0 spreads evenly, 1 runs only along the grain. */
  anisotropy: number;
  /** How fast suspended pigment settles into dense fibers. */
  absorb: number;
  /** Water lost per step. */
  evaporation: number;
  /** Extra drying at the wet edge, which pulls pigment out into a rim. */
  edgeRing: number;
  /** How fast a dried stain eases back into the page. */
  fade: number;
  /** Water below this is a pinned film that no longer travels. */
  pin: number;
  /** How much ink must pass before a cover is soaked through. */
  revealAt: number;
  /** Share of the moving water's pigment that keeps up with it. */
  carry: number;
  /** Pigment strength when composited. */
  strength: number;
  /** How much standing water darkens and glints. */
  sheen: number;
  /** How much the fiber sheet breaks up the stain. */
  grain: number;
  /** Simulation steps per animation frame. */
  substeps: number;
  /** A surface sleeps this long after its last drop. */
  lifetimeMs: number;
}

export type InkPreset = "typing" | "bleed" | "wick" | "stamp";

export const INK_PRESETS: Record<InkPreset, InkTuning> = {
  // A faint wet halo behind each new letter, dry in about half a second.
  typing: {
    cellPx: 3,
    flow: 0.13,
    anisotropy: 0.55,
    absorb: 0.012,
    evaporation: 0.012,
    edgeRing: 2.4,
    fade: 0.035,
    pin: 0.02,
    revealAt: 0.4,
    carry: 0.85,
    strength: 0.55,
    sheen: 0.55,
    grain: 0.35,
    substeps: 2,
    lifetimeMs: 1600,
  },
  // New words soaking up through the page.
  bleed: {
    cellPx: 2,
    flow: 0.15,
    anisotropy: 0.6,
    absorb: 0.02,
    evaporation: 0.006,
    edgeRing: 3,
    fade: 0.02,
    pin: 0.025,
    revealAt: 0.35,
    carry: 0.8,
    strength: 0.7,
    sheen: 0.7,
    grain: 0.4,
    substeps: 2,
    lifetimeMs: 2200,
  },
  // A strike line that wicks along its length.
  wick: {
    cellPx: 2,
    flow: 0.16,
    anisotropy: 0.75,
    absorb: 0.03,
    evaporation: 0.007,
    edgeRing: 2.2,
    fade: 0.012,
    pin: 0.02,
    revealAt: 0.4,
    carry: 0.9,
    strength: 1.4,
    sheen: 0.6,
    grain: 0.45,
    substeps: 2,
    lifetimeMs: 2600,
  },
  // Ink pooling at a stamp's edges, plus the spatter it throws.
  stamp: {
    cellPx: 2,
    flow: 0.12,
    anisotropy: 0.5,
    absorb: 0.025,
    evaporation: 0.005,
    edgeRing: 4,
    fade: 0.008,
    pin: 0.025,
    revealAt: 0.4,
    carry: 0.9,
    strength: 1.6,
    sheen: 0.8,
    grain: 0.5,
    substeps: 2,
    lifetimeMs: 3200,
  },
};

/** Sliders the lab exposes, with the range the step stays stable in. */
export const INK_TUNING_RANGES: Partial<
  Record<keyof InkTuning, { min: number; max: number; step: number }>
> = {
  flow: { min: 0.02, max: 0.2, step: 0.005 },
  anisotropy: { min: 0, max: 1, step: 0.05 },
  absorb: { min: 0, max: 0.08, step: 0.002 },
  evaporation: { min: 0.001, max: 0.03, step: 0.001 },
  edgeRing: { min: 0, max: 8, step: 0.1 },
  fade: { min: 0, max: 0.08, step: 0.002 },
  pin: { min: 0.005, max: 0.08, step: 0.005 },
  carry: { min: 0.2, max: 1, step: 0.05 },
  strength: { min: 0.1, max: 3, step: 0.05 },
  sheen: { min: 0, max: 1.5, step: 0.05 },
  grain: { min: 0, max: 0.9, step: 0.05 },
