input.content:
/**
 * Wet ink on WebGPU. One device, one set of WGSL pipelines and one fiber
 * sheet are shared; every place ink appears gets its own canvas surface
 * with its own field. All awake surfaces step and present in a single
 * submission per frame, and a surface with nothing wet on it costs nothing.
 *
 * The simulation never touches the text it sits under or over, so input,
 * selection and screen readers are unaffected by anything here.
 */
import commonWgsl from "./wgsl/common.wgsl?raw";
import fibersWgsl from "./wgsl/fibers.wgsl?raw";
import renderWgsl from "./wgsl/render.wgsl?raw";
import simWgsl from "./wgsl/sim.wgsl?raw";
import splatterWgsl from "./wgsl/splatter.wgsl?raw";
import {
  INK_PRESETS,
  parseComputedRgb,
  relativeLuminance,
  srgbToLinear,
  type InkPreset,
  type InkTuning,
} from "./tuning";

const FIBER_SIZE = 512;
const MAX_DROPS = 64;
const MAX_DROPLETS = 512;
const DROP_FLOATS = 8;
const DROPLET_FLOATS = 8;
const MASS_UNITS = 1024;
const MAX_DPR = 2;

export const INK_PREFERENCE_KEY = "twyne:ink:v1";

type Rgb = [number, number, number];

/** On unless the writer switched it off or asked for reduced motion. */
export function inkPreferred(): boolean {
  if (typeof window === "undefined") return false;
  if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) {
    return false;
  }
  try {
    return window.localStorage.getItem(INK_PREFERENCE_KEY) !== "off";
  } catch {
    return true;
  }
}

export function setInkPreferred(on: boolean): void {
  try {
    if (on) window.localStorage.removeItem(INK_PREFERENCE_KEY);
    else window.localStorage.setItem(INK_PREFERENCE_KEY, "off");
  } catch {
    // Private browsing: the choice lasts for this page only.
  }
  window.dispatchEvent(new CustomEvent("twyne:ink-preference", { detail: on }));
}

let economyHolds = 0;

/**
 * Local Live voice runs its model on the same GPU. While it holds this,
 * ink takes one simulation step per frame instead of its usual count.
 */
export function holdInkEconomy(): () => void {
  economyHolds++;
  let released = false;
  return () => {
    if (released) return;
    released = true;
    economyHolds = Math.max(0, economyHolds - 1);
  };
}

export interface InkStats {
  adapter: string;
  fps: number;
  /** Encoding and submitting one frame on the main thread. */
  cpuMs: number;
  /** GPU time for one frame, when the adapter exposes timestamps. */
  gpuMs: number | null;
  awake: number;
  economy: boolean;
}

export interface InkDrop {
  /** CSS pixels from the surface's top-left. */
  x: number;
  y: number;
  /** Lay the drop along a segment instead of a point. */
  toX?: number;
  toY?: number;
  radius: number;
  water: number;
  pigment: number;
  /** How much the fibers break up the drop's edge. */
  ragged?: number;
}

export interface InkSplatter {
  x: number;
  y: number;
  count: number;
  /** CSS pixels per frame at launch. */
  speed: number;
  /** Radians of the arc thrown; a full circle by default. */
  arc?: number;
  heading?: number;
  mass?: number;
}

export interface InkColors {
  /** sRGB 0..1. The page the canvas composites onto. */
  paper: Rgb;
  ink: Rgb;
  /** What hides content until ink soaks through it. Defaults to paper. */
  cover?: Rgb;
}

let enginePromise: Promise<InkEngine | null> | null = null;

/** The shared engine, or null where WebGPU is missing or ink is off. */
export function inkEngine(): Promise<InkEngine | null> {
  if (typeof navigator === "undefined" || !("gpu" in navigator)) {
    return Promise.resolve(null);
  }
  if (!inkPreferred()) return Promise.resolve(null);
  enginePromise ??= InkEngine.create().catch((err) => {
    console.warn("[twyne:ink] WebGPU unavailable", err);
    enginePromise = null;
    return null;
  });
  return enginePromise;
}

async function checkedModule(
  device: GPUDevice,
  label: string,
  source: string,
): Promise<GPUShaderModule> {
  const module = device.createShaderModule({
    label,
    code: `${commonWgsl}\n${source}`,
  });
  const info = await module.getCompilationInfo();
  const errors = info.messages.filter((m) => m.type === "error");
  if (errors.length) {
    throw new Error(
      `${label}: ${errors.map((m) => `${m.lineNum}:${m.linePos} ${m.message}`).join("; ")}`,
    );
  }
  return module;
}

interface Timestamps {
  set: GPUQuerySet;
  resolve: GPUBuffer;
  read: GPUBuffer;
  pending: boolean;
}

export class InkEngine {
  private readonly awake = new Set<InkSurface>();
  private readonly surfaces = new Set<InkSurface>();
  private frame = 0;
  private lastTick = 0;
  private dead = false;
  private timestamps: Timestamps | null = null;
  /** Collect GPU timings; the lab turns this on. */
  measure = false;
  readonly stats: InkStats;

  private constructor(
    readonly device: GPUDevice,
    readonly format: GPUTextureFormat,
    readonly fibers: GPUTexture,
    readonly simPipeline: GPUComputePipeline,
    readonly splatterPipeline: GPUComputePipeline,
    readonly renderPipeline: GPURenderPipeline,
    readonly fieldSampler: GPUSampler,
    readonly fiberSampler: GPUSampler,
    adapter: string,
  ) {
    this.stats = {
      adapter,
      fps: 0,
      cpuMs: 0,
      gpuMs: null,
      awake: 0,
      economy: false,
    };
    if (device.features.has("timestamp-query")) {
      this.timestamps = {
        set: device.createQuerySet({ type: "timestamp", count: 2 }),
        resolve: device.createBuffer({
          size: 16,
          usage: GPUBufferUsage.QUERY_RESOLVE | GPUBufferUsage.COPY_SRC,
        }),
        read: device.createBuffer({
          size: 16,
          usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
        }),
        pending: false,
      };
    }
    void device.lost.then((info) => {
      this.dead = true;
      enginePromise = null;
      if (info.reason !== "destroyed") {
        console.warn("[twyne:ink] device lost", info.message);
      }
      for (const surface of this.surfaces) surface.markLost();
    });
  }

  static async create(): Promise<InkEngine | null> {
    const adapter = await navigator.gpu.requestAdapter({
      powerPreference: "low-power",
    });
    if (!adapter) return null;
    const features: GPUFeatureName[] = adapter.features.has("timestamp-query")
      ? ["timestamp-query"]
      : [];
    const device = await adapter.requestDevice({
      label: "twyne ink",
      requiredFeatures: features,
    });
    const format = navigator.gpu.getPreferredCanvasFormat();
    const [fiberModule, simModule, splatterModule, renderModule] =
      await Promise.all([
        checkedModule(device, "ink fibers", fibersWgsl),
        checkedModule(device, "ink sim", simWgsl),
        checkedModule(device, "ink splatter", splatterWgsl),
        checkedModule(device, "ink render", renderWgsl),
      ]);
    const [fiberPipeline, simPipeline, splatterPipeline, renderPipeline] =
      await Promise.all([
        device.createComputePipelineAsync({
          label: "ink fibers",
          layout: "auto",
          compute: { module: fiberModule, entryPoint: "main" },
        }),
        device.createComputePipelineAsync({
          label: "ink sim",
          layout: "auto",
          compute: { module: simModule, entryPoint: "main" },
        }),
        device.createComputePipelineAsync({
          label: "ink splatter",
          layout: "auto",
          compute: { module: splatterModule, entryPoint: "main" },
        }),
        device.createRenderPipelineAsync({
          label: "ink render",
          layout: "auto",
          vertex: { module: renderModule, entryPoint: "vs" },
          fragment: {
            module: renderModule,
            entryPoint: "fs",
            targets: [{ format }],
          },
          primitive: { topology: "triangle-list" },
        }),
      ]);

    const fibers = device.createTexture({
      label: "ink fiber sheet",
      size: [FIBER_SIZE, FIBER_SIZE],
      format: "rgba8unorm",
      usage: GPUTextureUsage.STORAGE_BINDING | GPUTextureUsage.TEXTURE_BINDING,
    });
    const fiberParams = device.createBuffer({
      size: 16,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });
    const raw = new ArrayBuffer(16);
    new Uint32Array(raw, 0, 1)[0] = FIBER_SIZE;
    // Strand cell, grain angle (nearly level, as a sheet comes off the
    // wire), and how far strands stray from it.
    new Float32Array(raw, 4, 3).set([16, -0.06, 1.1]);
    device.queue.writeBuffer(fiberParams, 0, raw);
    const encoder = device.createCommandEncoder({ label: "ink fibers" });
    const pass = encoder.beginComputePass();
    pass.setPipeline(fiberPipeline);
    pass.setBindGroup(
      0,
      device.createBindGroup({
        layout: fiberPipeline.getBindGroupLayout(0),
        entries: [
          { binding: 0, resource: fibers.createView() },
          { binding: 1, resource: { buffer: fiberParams } },
        ],
      }),
    );
    pass.dispatchWorkgroups(FIBER_SIZE / 8, FIBER_SIZE / 8);
    pass.end();
    device.queue.submit([encoder.finish()]);
    fiberParams.destroy();

    const info = adapter.info;
    return new InkEngine(
      device,
      format,
      fibers,
      simPipeline,
      splatterPipeline,
      renderPipeline,
      device.createSampler({ magFilter: "linear", minFilter: "linear" }),
      device.createSampler({
        magFilter: "linear",
        minFilter: "linear",
        addressModeU: "repeat",
        addressModeV: "repeat",
      }),
      [info.vendor, info.architecture].filter(Boolean).join(" ") || "webgpu",
    );
  }

  get lost(): boolean {
    return this.dead;
  }

  /** A canvas of ink. Size it with `resize` before dropping anything. */
  surface(
    canvas: HTMLCanvasElement,
    tuning: InkPreset | InkTuning = "typing",
  ): InkSurface {
    const surface = new InkSurface(
      this,
      canvas,
      typeof tuning === "string" ? { ...INK_PRESETS[tuning] } : { ...tuning },
    );
    this.surfaces.add(surface);
    return surface;
  }

  /** @internal */
  forget(surface: InkSurface): void {
    this.surfaces.delete(surface);
    this.awake.delete(surface);
  }

  /** @internal */
  wake(surface: InkSurface): void {
    if (this.dead) return;
    const wasIdle = this.awake.size === 0;
    this.awake.add(surface);
    if (wasIdle) {
      this.lastTick = 0;
      requestAnimationFrame(this.tick);
    }
  }

  private readonly tick = (now: number): void => {
    if (this.dead || this.awake.size === 0) return;
    const started = performance.now();
    const economy = economyHolds > 0;
    const timed =
      this.measure && this.timestamps !== null && !this.timestamps.pending;
    const encoder = this.device.createCommandEncoder({ label: "ink frame" });
    const compute = encoder.beginComputePass(
      timed
        ? {
            timestampWrites: {
              querySet: this.timestamps!.set,
              beginningOfPassWriteIndex: 0,
            },
          }
        : undefined,
    );
    const surfaces = [...this.awake];
    for (const surface of surfaces) surface.step(compute, now, economy);
    compute.end();
    surfaces.forEach((surface, i) =>
      surface.render(
        encoder,
        now,
        timed && i === surfaces.length - 1 ? this.timestamps!.set : null,
      ),
    );
    if (timed) {
      const t = this.timestamps!;
      encoder.resolveQuerySet(t.set, 0, 2, t.resolve, 0);
      encoder.copyBufferToBuffer(t.resolve, 0, t.read, 0, 16);
    }
    this.device.queue.submit([encoder.finish()]);
    if (timed) this.readTimestamps();

    for (const surface of surfaces) {
      if (surface.asleep(now)) this.awake.delete(surface);
    }
    const cpu = performance.now() - started;
    const interval = this.lastTick ? now - this.lastTick : 0;
    this.lastTick = now;
    this.frame++;
    this.stats.cpuMs = ema(this.stats.cpuMs, cpu, this.frame);
    if (interval > 0) {
      this.stats.fps = ema(this.stats.fps, 1000 / interval, this.frame);
    }
    this.stats.awake = this.awake.size;
    this.stats.economy = economy;
    if (this.awake.size) requestAnimationFrame(this.tick);
  };

  private readTimestamps(): void {
    const t = this.timestamps!;
    t.pending = true;
    void t.read
      .mapAsync(GPUMapMode.READ)
      .then(() => {
        const [begin, end] = new BigUint64Array(t.read.getMappedRange());
        if (end > begin) {
          const ms = Number(end - begin) / 1e6;
          this.stats.gpuMs = ema(this.stats.gpuMs ?? ms, ms, this.frame);
        }
        t.read.unmap();
      })
      .catch(() => {})
      .finally(() => {
        t.pending = false;
      });
  }
}

function ema(previous: number, next: number, frame: number): number {
  const k = frame < 10 ? 0.5 : 0.08;
  return previous + (next - previous) * k;
}

interface Scheduled {
  at: number;
  drop: InkDrop;
}

export class InkSurface {
  private readonly context: GPUCanvasContext;
  private cssWidth = 0;
  private cssHeight = 0;
  private cols = 0;
  private rows = 0;
  private fields: [GPUTexture, GPUTexture] | null = null;
  private current = 0;
  private simGroups: GPUBindGroup[][] = [];
  private renderGroups: GPUBindGroup[] = [];
  private splat: GPUBuffer | null = null;
  private splatterGroup: GPUBindGroup | null = null;
  private readonly simParams: GPUBuffer;
  private readonly quietParams: GPUBuffer;
  private readonly renderParams: GPUBuffer;
  private readonly dropBuffer: GPUBuffer;
  private readonly droplets: GPUBuffer;
  private readonly splatterParams: GPUBuffer;
  private readonly dropData = new Float32Array(MAX_DROPS * DROP_FLOATS);
  private readonly fiberOffset: [number, number];
  private pending: InkDrop[] = [];
  private scheduled: Scheduled[] = [];
  private dropletCursor = 0;
  private dropletsUntil = 0;
  private lastActivity = 0;
  private revealStarted = 0;
  private wipe = false;
  private dead = false;
  private paper: Rgb = [0.98, 0.96, 0.9];
  private ink: Rgb = [0.12, 0.1, 0.08];
  private cover: Rgb = this.paper;
  private dark = false;
  /** Hide what is beneath until ink soaks through it. */
  revealing = false;
  /** Called once the first frame with a cover has been presented. */
  onPresented: (() => void) | null = null;

  constructor(
    private readonly engine: InkEngine,
    readonly canvas: HTMLCanvasElement,
    public tuning: InkTuning,
  ) {
    const device = engine.device;
    const context = canvas.getContext("webgpu");
    if (!context) throw new Error("Canvas has no WebGPU context");
    context.configure({
      device,
      format: engine.format,
      alphaMode: "premultiplied",
    });
    this.context = context;
    const uniform = GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST;
    this.simParams = device.createBuffer({ size: 64, usage: uniform });
    this.quietParams = device.createBuffer({ size: 64, usage: uniform });
    this.renderParams = device.createBuffer({ size: 96, usage: uniform });
    this.splatterParams = device.createBuffer({ size: 32, usage: uniform });
    this.dropBuffer = device.createBuffer({
      size: MAX_DROPS * DROP_FLOATS * 4,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    this.droplets = device.createBuffer({
      size: MAX_DROPLETS * DROPLET_FLOATS * 4,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    this.fiberOffset = [
      Math.floor(Math.random() * FIBER_SIZE),
      Math.floor(Math.random() * FIBER_SIZE),
    ];
  }

  get width(): number {
    return this.cssWidth;
  }

  get height(): number {
    return this.cssHeight;
  }

  /** Match the canvas to its box. Clears anything still wet. */
  resize(cssWidth: number, cssHeight: number): void {
    if (this.dead) return;
    const width = Math.max(1, Math.round(cssWidth));
    const height = Math.max(1, Math.round(cssHeight));
    const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
    this.canvas.width = Math.max(1, Math.round(width * dpr));
    this.canvas.height = Math.max(1, Math.round(height * dpr));
    const cols = Math.ceil(width / this.tuning.cellPx);
    const rows = Math.ceil(height / this.tuning.cellPx);
    this.cssWidth = width;
    this.cssHeight = height;
    if (cols === this.cols && rows === this.rows && this.fields) return;
    this.cols = cols;
    this.rows = rows;
    this.allocate();
  }

  setColors(colors: InkColors): void {
    this.paper = colors.paper;
    this.ink = colors.ink;
    this.cover = colors.cover ?? colors.paper;
    this.dark = relativeLuminance(colors.paper) < 0.3;
  }

  /** Read the page and ink colours from CSS, resolved against `el`. */
  readColors(el: Element, ink: string, cover?: string): void {
    const paper = backgroundBehind(el);
    this.setColors({
      paper,
      ink: resolveCssColor(el, ink) ?? this.ink,
      cover: cover ? (resolveCssColor(el, cover) ?? paper) : paper,
    });
  }

  drop(drop: InkDrop, delayMs = 0): void {
    if (this.dead || !this.fields) return;
    if (delayMs > 0) {
      this.scheduled.push({ at: performance.now() + delayMs, drop });
    } else {
      this.pending.push(drop);
    }
    this.touch();
  }

  /** A line of ink drawn from one point to another over `durationMs`. */
  stroke(
    from: { x: number; y: number },
    to: { x: number; y: number },
    durationMs: number,
    ink: Omit<InkDrop, "x" | "y" | "toX" | "toY">,
  ): void {
    const steps = Math.max(1, Math.round(durationMs / 16));
    for (let i = 0; i < steps; i++) {
      const a = i / steps;
      const b = (i + 1) / steps;
      // The pen loads at the start and runs drier toward the end.
      const load = 1.15 - 0.4 * a;
      this.drop(
        {
          ...ink,
          x: from.x + (to.x - from.x) * a,
          y: from.y + (to.y - from.y) * a,
          toX: from.x + (to.x - from.x) * b,
          toY: from.y + (to.y - from.y) * b,
          water: ink.water * load,
          pigment: ink.pigment * load,
        },
        i * (durationMs / steps),
      );
    }
  }

  /**
   * Seed a rectangle with drops that spread and merge, staggered so the
   * wet front arrives across it rather than all at once.
   */
  bleed(
    rect: { x: number; y: number; width: number; height: number },
    options: {
      seeds?: number;
      durationMs?: number;
      water?: number;
      pigment?: number;
    } = {},
  ): void {
    const seeds =
      options.seeds ?? Math.max(3, Math.round(rect.width / (rect.height * 0.9)));
    const duration = options.durationMs ?? 260;
    const radius = rect.height * 0.55;
    for (let i = 0; i < seeds; i++) {
      const t = (i + 0.5) / seeds;
      this.drop(
        {
          x: rect.x + rect.width * t + (Math.random() - 0.5) * radius * 0.6,
          y: rect.y + rect.height * (0.4 + Math.random() * 0.25),
          radius: radius * (0.85 + Math.random() * 0.4),
          water: options.water ?? 1.1,
          pigment: options.pigment ?? 0.16,
          ragged: 0.6,
        },
        t * duration,
      );
    }
  }

  splatter(s: InkSplatter): void {
    if (this.dead || !this.fields) return;
    const cell = this.tuning.cellPx;
    const count = Math.min(s.count, MAX_DROPLETS);
    const data = new Float32Array(count * DROPLET_FLOATS);
    const arc = s.arc ?? Math.PI * 2;
    const heading = s.heading ?? 0;
    for (let i = 0; i < count; i++) {
      const angle = heading + (Math.random() - 0.5) * arc;
      const speed = (s.speed / cell) * (0.35 + Math.random() ** 1.6 * 1.2);
      const o = i * DROPLET_FLOATS;
      data[o] = s.x / cell;
      data[o + 1] = s.y / cell;
      data[o + 2] = Math.cos(angle) * speed;
      data[o + 3] = Math.sin(angle) * speed;
      data[o + 4] = 0.2 + Math.random() * 0.4;
      data[o + 5] = 0.25 + Math.random() * 0.6;
      data[o + 6] = (s.mass ?? 0.5) * (0.3 + Math.random() ** 2 * 1.6);
      data[o + 7] = 1;
    }
    // Ring buffer: the newest throw overwrites the oldest droplets.
    const first = Math.min(count, MAX_DROPLETS - this.dropletCursor);
    const queue = this.engine.device.queue;
    queue.writeBuffer(
      this.droplets,
      this.dropletCursor * DROPLET_FLOATS * 4,
      data,
      0,
      first * DROPLET_FLOATS,
    );
    if (first < count) {
      queue.writeBuffer(
        this.droplets,
        0,
        data,
        first * DROPLET_FLOATS,
        (count - first) * DROPLET_FLOATS,
      );
    }
    this.dropletCursor = (this.dropletCursor + count) % MAX_DROPLETS;
    this.dropletsUntil = performance.now() + 1500;
    this.touch();
  }

  /** Start a reveal: everything beneath is covered until ink reaches it. */
  beginReveal(): void {
    this.revealing = true;
    this.revealStarted = performance.now();
    this.wipe = true;
    this.touch();
  }

  /** Dry everything at once. */
  clear(): void {
    this.pending = [];
    this.scheduled = [];
    this.revealing = false;
    this.wipe = true;
    this.touch();
  }

  destroy(): void {
    if (this.dead) return;
    this.dead = true;
    this.engine.forget(this);
    this.fields?.forEach((t) => t.destroy());
    for (const buffer of [
      this.splat,
      this.simParams,
      this.quietParams,
      this.renderParams,
      this.dropBuffer,
      this.droplets,
      this.splatterParams,
    ]) {
      buffer?.destroy();
    }
    try {
      this.context.unconfigure();
    } catch {
      // Already gone with the device.
    }
  }

  /** @internal */
  markLost(): void {
    this.dead = true;
  }

  private touch(): void {
    this.lastActivity = performance.now();
    this.engine.wake(this);
  }

  private allocate(): void {
    const device = this.engine.device;
    this.fields?.forEach((t) => t.destroy());
    this.splat?.destroy();
    const make = (label: string) =>
      device.createTexture({
        label,
        size: [this.cols, this.rows],
        format: "rgba16float",
        usage:
          GPUTextureUsage.STORAGE_BINDING |
          GPUTextureUsage.TEXTURE_BINDING |
          GPUTextureUsage.RENDER_ATTACHMENT,
      });
    this.fields = [make("ink field a"), make("ink field b")];
    this.current = 0;
    this.splat = device.createBuffer({
      size: this.cols * this.rows * 4,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    const views = this.fields.map((t) => t.createView());
    const simLayout = this.engine.simPipeline.getBindGroupLayout(0);
    const fiberView = this.engine.fibers.createView();
    this.simGroups = [0, 1].map((from) =>
      [this.quietParams, this.simParams].map((params) =>
        device.createBindGroup({
          layout: simLayout,
          entries: [
            { binding: 0, resource: views[from] },
            { binding: 1, resource: views[1 - from] },
            { binding: 2, resource: fiberView },
            { binding: 3, resource: { buffer: params } },
            { binding: 4, resource: { buffer: this.dropBuffer } },
            { binding: 5, resource: { buffer: this.splat! } },
          ],
        }),
      ),
    );
    const renderLayout = this.engine.renderPipeline.getBindGroupLayout(0);
    this.renderGroups = [0, 1].map((i) =>
      device.createBindGroup({
        layout: renderLayout,
        entries: [
          { binding: 0, resource: views[i] },
          { binding: 1, resource: this.engine.fieldSampler },
          { binding: 2, resource: fiberView },
          { binding: 3, resource: this.engine.fiberSampler },
          { binding: 4, resource: { buffer: this.renderParams } },
        ],
      }),
    );
    this.splatterGroup = device.createBindGroup({
      layout: this.engine.splatterPipeline.getBindGroupLayout(0),
      entries: [
        { binding: 0, resource: { buffer: this.droplets } },
        { binding: 1, resource: { buffer: this.splat } },
        { binding: 2, resource: { buffer: this.splatterParams } },
      ],
    });
    // Old droplets would land in the wrong place on a new grid.
    device.queue.writeBuffer(
      this.droplets,
      0,
      new Float32Array(MAX_DROPLETS * DROPLET_FLOATS),
    );
  }

  private writeSimParams(buffer: GPUBuffer, dropCount: number): void {
    const t = this.tuning;
    const raw = new ArrayBuffer(64);
    const u = new Uint32Array(raw);
    const f = new Float32Array(raw);
    u[0] = this.cols;
    u[1] = this.rows;
    u[2] = this.fiberOffset[0];
    u[3] = this.fiberOffset[1];
    f[4] = t.flow;
    f[5] = t.anisotropy;
    f[6] = t.absorb;
    f[7] = t.evaporation;
    f[8] = t.edgeRing;
    f[9] = t.fade;
    f[10] = t.pin;
    f[11] = t.revealAt;
    u[12] = dropCount;
    f[13] = 1 / MASS_UNITS;
    f[14] = t.cellPx;
    f[15] = t.carry;
    this.engine.device.queue.writeBuffer(buffer, 0, raw);
  }

  /** @internal */
  step(pass: GPUComputePassEncoder, now: number, economy: boolean): void {
    if (this.dead || !this.fields) return;
    const device = this.engine.device;
    if (this.wipe) {
      this.wipe = false;
      const zeros = new Uint8Array(this.cols * this.rows * 8);
      for (const field of this.fields) {
        device.queue.writeTexture(
          { texture: field },
          zeros,
          { bytesPerRow: this.cols * 8 },
          [this.cols, this.rows],
        );
      }
      device.queue.writeBuffer(this.splat!, 0, new Uint32Array(this.cols * this.rows));
    }

    if (this.scheduled.length) {
      const due = this.scheduled.filter((s) => s.at <= now);
      if (due.length) {
        this.scheduled = this.scheduled.filter((s) => s.at > now);
        this.pending.push(...due.map((s) => s.drop));
        this.lastActivity = now;
      }
    }
    const drops = this.pending.splice(0, MAX_DROPS);
    const cell = this.tuning.cellPx;
    drops.forEach((d, i) => {
      const o = i * DROP_FLOATS;
      this.dropData[o] = d.x / cell;
      this.dropData[o + 1] = d.y / cell;
      this.dropData[o + 2] = (d.toX ?? d.x) / cell;
      this.dropData[o + 3] = (d.toY ?? d.y) / cell;
      this.dropData[o + 4] = Math.max(d.radius / cell, 0.75);
      this.dropData[o + 5] = d.water;
      this.dropData[o + 6] = d.pigment;
      this.dropData[o + 7] = d.ragged ?? 0.4;
    });
    if (drops.length) {
      device.queue.writeBuffer(
        this.dropBuffer,
        0,
        this.dropData,
        0,
        drops.length * DROP_FLOATS,
      );
    }
    this.writeSimParams(this.simParams, drops.length);
    this.writeSimParams(this.quietParams, 0);

    if (now < this.dropletsUntil) {
      const raw = new ArrayBuffer(32);
      const u = new Uint32Array(raw);
      const f = new Float32Array(raw);
      u[0] = this.cols;
      u[1] = this.rows;
      u[2] = MAX_DROPLETS;
      f[3] = 0.045; // gravity, in launch heights per frame²
      f[4] = 0.9; // air drag
      device.queue.writeBuffer(this.splatterParams, 0, raw);
      pass.setPipeline(this.engine.splatterPipeline);
      pass.setBindGroup(0, this.splatterGroup!);
      pass.dispatchWorkgroups(Math.ceil(MAX_DROPLETS / 64));
    }

    const substeps = economy ? 1 : this.tuning.substeps;
    pass.setPipeline(this.engine.simPipeline);
    for (let k = 0; k < substeps; k++) {
      const withDrops = k === 0 && drops.length > 0 ? 1 : 0;
      pass.setBindGroup(0, this.simGroups[this.current][withDrops]);
      pass.dispatchWorkgroups(Math.ceil(this.cols / 8), Math.ceil(this.rows / 8));
      this.current = 1 - this.current;
    }
  }

  /** @internal */
  render(
    encoder: GPUCommandEncoder,
    now: number,
    timestamps: GPUQuerySet | null,
  ): void {
    if (this.dead || !this.fields) return;
    const sleeping = this.asleep(now);
    const raw = new Float32Array(24);
    raw.set(this.paper.map(srgbToLinear), 0);
    raw[3] = this.tuning.strength;
    raw.set(this.ink.map(srgbToLinear), 4);
    raw[7] = this.tuning.sheen;
    raw.set(this.cover.map(srgbToLinear), 8);
    raw[11] = this.revealing && !sleeping ? 1 : 0;
    raw[12] = 1 / this.cols;
    raw[13] = 1 / this.rows;
    raw[14] = this.cssWidth / FIBER_SIZE;
    raw[15] = this.cssHeight / FIBER_SIZE;
    raw[16] = this.fiberOffset[0] / FIBER_SIZE;
    raw[17] = this.fiberOffset[1] / FIBER_SIZE;
    raw[18] = this.dark ? 1 : 0;
    raw[19] = this.tuning.grain;
    // A cover lifts by the end of the surface's life even where ink never
    // reached, so nothing beneath stays hidden.
    const age = now - this.revealStarted;
    const life = this.tuning.lifetimeMs;
    raw[20] = Math.min(1, Math.max(0, (age - life * 0.45) / (life * 0.35)));
    this.engine.device.queue.writeBuffer(this.renderParams, 0, raw);

    const pass = encoder.beginRenderPass({
      colorAttachments: [
        {
          view: this.context.getCurrentTexture().createView(),
          clearValue: { r: 0, g: 0, b: 0, a: 0 },
          loadOp: "clear",
          storeOp: "store",
        },
      ],
      timestampWrites: timestamps
        ? { querySet: timestamps, endOfPassWriteIndex: 1 }
        : undefined,
    });
    // The last frame of a surface only clears it.
    if (!sleeping) {
      pass.setPipeline(this.engine.renderPipeline);
      pass.setBindGroup(0, this.renderGroups[this.current]);
      pass.draw(3);
    }
    pass.end();
    if (this.revealing && this.onPresented) {
      const presented = this.onPresented;
      this.onPresented = null;
      requestAnimationFrame(() => presented());
    }
    if (sleeping) {
      this.revealing = false;
      this.wipe = true;
    }
  }

  /** @internal */
  asleep(now: number): boolean {
    return (
      this.dead ||
      (this.pending.length === 0 &&
        this.scheduled.length === 0 &&
        now > this.dropletsUntil &&
        now - this.lastActivity > this.tuning.lifetimeMs)
    );
  }
}

/** Resolve any CSS colour (custom properties included) to sRGB 0..1. */
export function resolveCssColor(el: Element, value: string): Rgb | null {
  const probe = document.createElement("span");
  probe.style.color = value;
  probe.style.display = "none";
  el.appendChild(probe);
  const rgb = parseComputedRgb(getComputedStyle(probe).color);
  probe.remove();
  return rgb;
}

/** The first opaque background at or behind `el`: the page it sits on. */
export function backgroundBehind(el: Element): Rgb {
  for (let node: Element | null = el; node; node = node.parentElement) {
    const rgb = parseComputedRgb(getComputedStyle(node).backgroundColor);
    if (rgb) return rgb;
  }
  return resolveCssColor(el, "var(--color-paper)") ?? [0.96, 0.93, 0.85];
}

