/**
 * Wet ink under the writer's own letters. A band of canvas follows the
 * caret beneath the text column; each typed character leaves a faint halo
 * that soaks into the grain and dries. Nothing here reads or delays input:
 * it runs after the browser has already put the letter on the page.
 */
import { inkEngine, type InkSurface } from "./engine";

export interface CaretBox {
  left: number;
  top: number;
  bottom: number;
}

export interface PageInk {
  /** Call after a character lands; reads the caret on the next frame. */
  keystroke(): void;
  destroy(): void;
}

const BAND = 360;
const EDGE = 72;
const COLOR_TTL_MS = 1500;

/**
 * `host` is the positioned page the band lives in, beneath its text.
 * `caret` returns the caret's client box, or null when there isn't one.
 */
export async function attachPageInk(
  host: HTMLElement,
  caret: () => CaretBox | null,
): Promise<PageInk | null> {
  const engine = await inkEngine();
  if (!engine || !host.isConnected) return null;

  const canvas = document.createElement("canvas");
  canvas.className = "ink-page-band";
  canvas.setAttribute("aria-hidden", "true");
  host.prepend(canvas);
  const surface: InkSurface = engine.surface(canvas, "typing");
  let bandTop = 0;
  let colorsAt = 0;
  let frame = 0;

  const fit = () => {
    const height = Math.min(BAND, Math.max(host.clientHeight, 1));
    canvas.style.height = `${height}px`;
    canvas.style.width = `${host.clientWidth}px`;
    surface.resize(host.clientWidth, height);
  };
  fit();
  const resize = new ResizeObserver(fit);
  resize.observe(host);

  const land = () => {
    frame = 0;
    const box = caret();
    if (!box) return;
    const hostBox = host.getBoundingClientRect();
    const x = box.left - hostBox.left - host.clientLeft;
    const top = box.top - hostBox.top - host.clientTop;
    const lineHeight = Math.max(8, box.bottom - box.top);
    // Keep the caret in the band's middle; moving it drops what's wet.
    if (top < bandTop + EDGE || top + lineHeight > bandTop + surface.height - EDGE) {
      const limit = Math.max(0, host.clientHeight - surface.height);
      bandTop = Math.min(limit, Math.max(0, top - surface.height / 2));
      canvas.style.top = `${bandTop}px`;
      surface.clear();
    }
    const now = performance.now();
    if (now - colorsAt > COLOR_TTL_MS) {
      surface.readColors(host, "var(--color-ink)");
      colorsAt = now;
    }
    // The letter just typed sits left of the caret.
    surface.drop({
      x: x - lineHeight * 0.18 + (Math.random() - 0.5) * 2,
      y: top - bandTop + lineHeight * 0.55,
      radius: lineHeight * (0.36 + Math.random() * 0.08),
      water: 0.62,
      pigment: 0.05,
      ragged: 0.8,
    });
  };

  return {
    keystroke() {
      if (!frame) frame = requestAnimationFrame(land);
    },
    destroy() {
      cancelAnimationFrame(frame);
      resize.disconnect();
      surface.destroy();
      canvas.remove();
    },
  };
}

/** Typed characters, not deletions, pastes or drops. */
export function isTypedInput(event: Event): boolean {
  const type = (event as InputEvent).inputType;
  return (
    type === "insertText" ||
    type === "insertCompositionText" ||
    type === "insertReplacementText"
  );
}

