  type NoSerialize,
} from "@qwik.dev/core";
import { WorkflowStamp } from "../ui/workflow-stamp";
import { CleanProofStamp } from "../ui/clean-proof-stamp";
import {
  holdInkEconomy,
  inkEngine,
  type InkStats,
  type InkSurface,
} from "../../utils/ink/engine";
import {
  inkReveal,
  inkStampPool,
  inkStrike,
  lineRects,
} from "../../utils/ink/moments";
import { attachPageInk, isTypedInput } from "../../utils/ink/page-ink";
import {
  INK_PRESETS,
  INK_TUNING_RANGES,
  type InkPreset,
  type InkTuning,
} from "../../utils/ink/tuning";

const SENTENCE =
  "The ferry left at dawn, and by the time the fog lifted the harbour was a rumour behind us.";

const wait = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** One row of the lab: today's behaviour beside the ink version. */
export const InkPair = component$<{ title: string; note: string }>((props) => (
  <section class="mb-10">
    <header class="mb-3 flex items-baseline justify-between gap-4">
      <h3 class="text-lg" style="font-family: var(--font-display)">
        {props.title}
      </h3>
      <Slot name="actions" />
    </header>
    <p class="mb-3 max-w-[60ch] text-sm text-[color:var(--color-ink-light)]">
      {props.note}
    </p>
