/** A sentence typed out at a writer's rhythm, with or without wet ink. */
export const TypingDemo = component$<{ ink: boolean; replay: number }>(
  (props) => {
    const host = useSignal<HTMLDivElement>();
    const line = useSignal<HTMLParagraphElement>();
    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(async ({ track, cleanup }) => {
      track(() => props.replay);
      const el = host.value;
      const p = line.value;
      if (!el || !p) return;
      let stopped = false;
      cleanup(() => (stopped = true));
      p.textContent = "";
      const text = document.createTextNode("");
      p.appendChild(text);
      const caret = () => {
        const range = document.createRange();
        range.setStart(text, text.length);
        range.collapse(true);
        const box = range.getBoundingClientRect();
        return box.height ? box : null;
      };
      const page = props.ink ? await attachPageInk(el, caret) : null;
      cleanup(() => page?.destroy());
      await wait(350);
      for (const ch of SENTENCE) {
        if (stopped) return;
        text.appendData(ch);
        page?.keystroke();
        const pause = ch === " " ? 70 : /[,.]/.test(ch) ? 260 : 0;
        await wait(42 + Math.random() * 55 + pause);
      }
    });
    return (
      <div
        ref={host}
        class="paper-sheet ink-page-host relative min-h-[9.5rem] px-6 py-5"
      >
        <p
          ref={line}
          class="text-[1.125rem] leading-[1.8]"
          style="font-family: var(--font-serif)"
        />
      </div>
    );
  },
);

/** Accepting a proposed edit: struck words give way to the new ones. */
export const AcceptDemo = component$<{ ink: boolean; replay: number }>(
  (props) => {
    const host = useSignal<HTMLDivElement>();
    const target = useSignal<HTMLSpanElement>();
    const stamp = useSignal(0);
    const state = useStore({ accepted: false });
    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(async ({ track }) => {
      track(() => props.replay);
      const el = host.value;
      const span = target.value;
      if (!el || !span) return;
      state.accepted = false;
      span.textContent = "voted in favour of approving";
      await wait(700);
      if (props.ink) {
        const range = document.createRange();
        range.selectNodeContents(span);
        await inkStrike(el, lineRects(range));
        await wait(320);
      }
      state.accepted = true;
      span.textContent = "approved";
      stamp.value++;
      if (props.ink) {
        await new Promise((r) => requestAnimationFrame(r));
        const range = document.createRange();
        range.selectNodeContents(span);
        await inkReveal(el, lineRects(range));
      }
    });
    return (
      <div
        ref={host}
        class="paper-sheet relative min-h-[9.5rem] overflow-hidden px-6 py-5"
      >
        <p
          class="text-[1.125rem] leading-[1.8]"
          style="font-family: var(--font-serif)"
        >
          After a long night the committee{" "}
          <span ref={target} class={{ "twyne-suggestion": !state.accepted }}>
            voted in favour of approving
          </span>{" "}
          the measure.
        </p>
        {stamp.value > 0 && (
          <div
            key={stamp.value}
            class="lab-approval-stamp pointer-events-none absolute right-3 top-1 w-24"
          >
            <WorkflowStamp kind="revised" impressionKey={stamp.value} />
          </div>
        )}
      </div>
    );
  },
);

const NOTES = [
  "Is “rumour” doing too much here?",
  "Cite the ferry timetable.",
  "Lovely — keep this.",
];

/** The margin empties, and the proof is stamped clean. */
export const CleanProofDemo = component$<{ ink: boolean; replay: number }>(
  (props) => {
    const host = useSignal<HTMLDivElement>();
    const slot = useSignal<HTMLDivElement>();
    const state = useStore({ open: NOTES.length, stamped: 0 });
    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(async ({ track }) => {
      track(() => props.replay);
      state.open = NOTES.length;
      state.stamped = 0;
      await wait(600);
      for (let i = NOTES.length; i > 0; i--) {
        state.open = i - 1;
        await wait(380);
      }
      state.stamped = props.replay + 1;
      if (!props.ink) return;
      // The die meets the paper about a third of the way through its press.
      await new Promise((r) => requestAnimationFrame(r));
      const tool = slot.value?.querySelector<HTMLImageElement>(".ink-stamp__tool");
      if (tool && !tool.complete) {
        await new Promise((r) => tool.addEventListener("load", r, { once: true }));
      }
      await wait(160);
      const el = host.value;
      const mark = slot.value?.querySelector(".clean-proof-stamp__mark");
      if (el && mark) await inkStampPool(el, mark.getBoundingClientRect());
    });
    return (
      <div
        ref={host}
        class="paper-sheet relative grid min-h-[13rem] grid-cols-[1fr_9rem] gap-4 overflow-hidden px-6 py-5"
      >
        <p
          class="text-[1.05rem] leading-[1.8]"
          style="font-family: var(--font-serif)"
        >
          The ferry left at dawn, and by the time the fog lifted the harbour
          was a rumour behind us.
        </p>
        <div class="relative">
          {NOTES.map((note, i) => (
            <p
              key={note}
              class="mb-2 rounded-sm border border-[color:var(--color-paper-3)] bg-[color:var(--color-paper-soft)] px-2 py-1 text-xs transition-all duration-300"
              style={{
                opacity: i < state.open ? 1 : 0,
                transform: i < state.open ? "none" : "translateX(1.5rem)",
              }}
            >
              {note}
            </p>
          ))}
          <div
            ref={slot}
            class="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2"
          >
            {state.stamped > 0 && (
              <CleanProofStamp impressionKey={state.stamped} />
            )}
          </div>
        </div>
      </div>
    );
  },
);

