/** Live engine numbers: what this device spends on the ink. */
export const InkStatsReadout = component$(() => {
  const stats = useStore<InkStats & { available: boolean | null }>({
    available: null,
    adapter: "",
    fps: 0,
    cpuMs: 0,
    gpuMs: null,
    awake: 0,
    economy: false,
  });
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ cleanup }) => {
    const engine = await inkEngine();
    stats.available = !!engine;
    if (!engine) return;
    engine.measure = true;
    const timer = setInterval(() => Object.assign(stats, engine.stats), 250);
    cleanup(() => {
      clearInterval(timer);
      engine.measure = false;
    });
  });
  return (
    <p
      class="ink-lab-stats mb-6 font-[family-name:var(--font-typewriter)] text-xs text-[color:var(--color-ink-muted)]"
      data-available={String(stats.available)}
    >
      {stats.available === null
        ? "Starting the ink engine…"
        : stats.available
          ? `${stats.adapter} · ${stats.awake ? `${stats.fps.toFixed(0)} fps` : "asleep"} · CPU ${stats.cpuMs.toFixed(2)} ms · GPU ${stats.gpuMs === null ? "n/a" : `${stats.gpuMs.toFixed(2)} ms`}${stats.economy ? " · economy" : ""}`
          : "WebGPU is unavailable here, or ink is switched off: the After column shows the plain fallback."}
    </p>
  );
});

type ToolName = "drop" | "strike" | "bleed" | "stamp";

/** Tune a preset by hand on a scratch sheet, and type into it. */
export const InkPlayground = component$(() => {
  const host = useSignal<HTMLDivElement>();
  const sheet = useSignal<HTMLDivElement>();
  const editable = useSignal<HTMLDivElement>();
  const surface = useSignal<NoSerialize<InkSurface>>();
  const state = useStore<{
    preset: InkPreset;
    tuning: InkTuning;
    tool: ToolName;
    economy: boolean;
  }>({
    preset: "typing",
    tuning: { ...INK_PRESETS.typing },
    tool: "drop",
    economy: false,
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ cleanup }) => {
    const el = sheet.value;
    const typing = host.value;
    const input = editable.value;
    if (!el || !typing || !input) return;
    const engine = await inkEngine();
    if (!engine) return;
    const canvas = document.createElement("canvas");
    canvas.className = "ink-page-band";
    canvas.style.width = "100%";
    canvas.style.height = "100%";
    el.prepend(canvas);
    const s = engine.surface(canvas, state.tuning);
    s.resize(el.clientWidth, el.clientHeight);
    s.readColors(el, "var(--color-ink)");
    surface.value = noSerialize(s);
    const page = await attachPageInk(typing, () => {
      const sel = window.getSelection();
      if (!sel?.rangeCount) return null;
      const box = sel.getRangeAt(0).getBoundingClientRect();
      return box.height ? box : null;
    });
    const onInput = (e: Event) => isTypedInput(e) && page?.keystroke();
    input.addEventListener("input", onInput);
    cleanup(() => {
      input.removeEventListener("input", onInput);
      page?.destroy();
      s.destroy();
      canvas.remove();
    });
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ track }) => {
    const tuning = { ...track(() => state.tuning) };
    for (const key of Object.keys(tuning) as (keyof InkTuning)[]) {
      track(() => state.tuning[key]);
    }
    const s = surface.value;
    const el = sheet.value;
    if (!s || !el) return;
    const resized = s.tuning.cellPx !== tuning.cellPx;
    s.tuning = tuning;
    if (resized) s.resize(el.clientWidth, el.clientHeight);
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ track, cleanup }) => {
    if (!track(() => state.economy)) return;
    cleanup(holdInkEconomy());
  });

  return (
    <div class="grid gap-6 p-8 lg:grid-cols-[18rem_1fr]" style="max-width: 76rem">
      <aside class="space-y-3 text-sm">
        <InkStatsReadout />
        <label class="block">
          Preset
          <select
            class="ml-2"
            value={state.preset}
            onChange$={(_, el) => {
              state.preset = el.value as InkPreset;
              state.tuning = { ...INK_PRESETS[state.preset] };
            }}
          >
            {(Object.keys(INK_PRESETS) as InkPreset[]).map((p) => (
              <option key={p} value={p}>
                {p}
              </option>
            ))}
          </select>
        </label>
        {(Object.keys(INK_TUNING_RANGES) as (keyof InkTuning)[]).map((key) => {
          const range = INK_TUNING_RANGES[key]!;
          return (
            <label key={key} class="block">
              <span class="flex justify-between">
                <span>{key}</span>
                <span class="tabular-nums">{state.tuning[key]}</span>
              </span>
              <input
                type="range"
                class="w-full"
                min={range.min}
                max={range.max}
                step={range.step}
                value={state.tuning[key]}
                onInput$={(_, el) => {
                  state.tuning = { ...state.tuning, [key]: Number(el.value) };
                }}
              />
            </label>
          );
        })}
        <label class="flex items-center gap-2">
          <input
            type="checkbox"
            checked={state.economy}
            onChange$={(_, el) => (state.economy = el.checked)}
          />
          Economy (as while Live voice runs)
        </label>
      </aside>
      <div class="space-y-4">
        <div class="flex flex-wrap gap-2">
          {(["drop", "strike", "bleed", "stamp"] as ToolName[]).map((tool) => (
            <button
              key={tool}
              class={state.tool === tool ? "btn-press" : "btn-paper"}
              onClick$={() => (state.tool = tool)}
            >
              {tool}
            </button>
          ))}
          <button class="btn-paper" onClick$={() => surface.value?.clear()}>
            Dry it all
          </button>
        </div>
        <div
          ref={sheet}
          class="paper-sheet ink-page-host relative h-[22rem] cursor-crosshair overflow-hidden"
          onPointerDown$={(e, el) => {
            const s = surface.value;
            if (!s) return;
            const box = el.getBoundingClientRect();
            const x = e.clientX - box.left;
            const y = e.clientY - box.top;
            if (state.tool === "drop") {
              s.drop({ x, y, radius: 14, water: 1.2, pigment: 0.25, ragged: 0.7 });
            } else if (state.tool === "strike") {
              s.stroke({ x, y }, { x: x + 220, y }, 360, {
                radius: 1.6,
                water: 1.3,
                pigment: 0.55,
              });
            } else if (state.tool === "bleed") {
              s.bleed({ x, y: y - 12, width: 180, height: 24 });
            } else {
              s.splatter({ x, y, count: 120, speed: 3.2, mass: 0.5 });
            }
          }}
        >
          <p class="pointer-events-none select-none p-4 text-xs text-[color:var(--color-ink-muted)]">
            Click to use the tool on a scratch sheet.
          </p>
        </div>
        <div
          ref={host}
          class="paper-sheet ink-page-host relative min-h-[10rem] px-6 py-5"
        >
          <div
            ref={editable}
            contentEditable="true"
            class="min-h-[8rem] text-[1.125rem] leading-[1.8] outline-none"
            style="font-family: var(--font-serif)"
          >
            Type here to feel the typing preset.
          </div>
        </div>
      </div>
    </div>
  );
});

