import { component$, useSignal, useVisibleTask$ } from "@qwik.dev/core";
import { INK_PREFERENCE_KEY, setInkPreferred } from "../../utils/ink/engine";

/** The one switch for wet ink on this device. */
export const WetInkSetting = component$(() => {
  const on = useSignal(true);
  const reduced = useSignal(false);
  const supported = useSignal(true);
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(() => {
    supported.value = "gpu" in navigator;
    reduced.value = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    ).matches;
    try {
      on.value = localStorage.getItem(INK_PREFERENCE_KEY) !== "off";
    } catch {
      on.value = true;
    }
  });
  const note = !supported.value
    ? "This browser has no WebGPU, so the page stays dry."
    : reduced.value
      ? "Off while your system asks for reduced motion."
      : "Letters soak into the page as you type; accepted edits ink in.";
  return (
    <label class="mt-4 flex cursor-pointer items-center justify-between border-t border-dashed border-[var(--color-paper-3)] pt-4">
      <div>
        <span
          class="block text-sm text-[var(--color-ink)]"
          style={{ fontFamily: "var(--font-display)" }}
        >
          Wet ink
        </span>
        <span
          class="text-[0.65rem] text-[var(--color-ink-muted)]"
          style={{ fontFamily: "var(--font-typewriter)" }}
        >
          {note}
        </span>
      </div>
      <input
        type="checkbox"
        checked={on.value}
        disabled={!supported.value}
        onChange$={(_, el) => {
          on.value = el.checked;
          setInkPreferred(el.checked);
        }}
        class="sr-only"
      />
      <span
        class={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${
          on.value && supported.value
            ? "bg-[var(--color-vermilion)]"
            : "bg-[var(--color-paper-3)]"
        }`}
      >
        <span
          class={`inline-block h-3.5 w-3.5 transform rounded-full bg-[var(--color-paper)] transition-transform ${
            on.value && supported.value ? "translate-x-5" : "translate-x-1"
          }`}
        />
      </span>
    </label>
  );
});

