/** Accepting a proposed edit: struck words give way to the new ones. */
export const AcceptDemo = component$<{ ink: boolean; replay: number }>(
  (props) => {
    const host = useSignal<HTMLDivElement>();
    const target = useSignal<HTMLSpanElement>();
    const stamp = useSignal(0);
    const state = useStore({ accepted: false });
    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(async ({ track, cleanup }) => {
      track(() => props.replay);
      const el = host.value;
      const span = target.value;
      if (!el || !span) return;
      let stopped = false;
      cleanup(() => {
        stopped = true;
      });
      const wait = (ms: number) =>
        new Promise<void>((resolve, reject) =>
          setTimeout(() => (stopped ? reject(new Error("replayed")) : resolve()), ms),
        );
      state.accepted = false;
      span.style.opacity = "";
      span.textContent = "voted in favour of approving";
      await wait(700);
      if (props.ink) {
        const range = document.createRange();
        range.selectNodeContents(span);
        const strike = await inkStrike(el, lineRects(range));
        if (strike) {
          await strike.drawn;
          await wait(260);
          // The struck words lift away with their strike.
          span.style.transition = "opacity 180ms ease-out";
          span.style.opacity = "0";
          strike.lift(180);
          await wait(200);
          span.style.transition = "";
          span.style.opacity = "";
        }
      }
      state.accepted = true;
      span.textContent = "approved";
      stamp.value++;
      if (props.ink) {
        await new Promise((r) => requestAnimationFrame(r));
        const range = document.createRange();
        range.selectNodeContents(span);
        await inkReveal(el, lineRects(range));
      }
