import { component$, useSignal, useVisibleTask$ } from "@qwik.dev/core";
import { StampPress } from "./stamp-press";
import { inkStampPool } from "../../utils/ink/moments";

/** Stamped once every note on the proof has been answered. */
export const CleanProofStamp = component$<{
  animated?: boolean;
  impressionKey?: string | number;
}>((props) => (
  <span class="clean-proof-stamp" role="img" aria-label="Clean proof">
    <StampPress
      key={props.impressionKey ?? 0}
      animated={props.animated ?? true}
    >
      <span class="clean-proof-stamp__mark">
        <small>Nothing left</small>
        <b>Clean</b>
        <small>Proof</small>
      </span>
    </StampPress>
  </span>
));

/**
 * The stamp coming down, and with wet ink, the rim it squeezes out and the
 * spatter it throws. The ink lands as the die meets the paper.
 */
export const CleanProofMoment = component$<{
  impressionKey: number;
  ink?: boolean;
}>((props) => {
  const host = useSignal<HTMLDivElement>();
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ track }) => {
    track(() => props.impressionKey);
    const el = host.value;
    if (!el || props.ink === false) return;
    await new Promise((r) => requestAnimationFrame(r));
    const tool = el.querySelector<HTMLImageElement>(".ink-stamp__tool");
    if (tool && !tool.complete) {
      await new Promise((r) =>
        tool.addEventListener("load", r, { once: true }),
      );
    }
    // stamp-die-press reaches the paper about a third of the way in.
    await new Promise((r) => setTimeout(r, 160));
    const mark = el.querySelector(".clean-proof-stamp__mark");
    if (mark?.isConnected) {
      await inkStampPool(el, mark.getBoundingClientRect());
    }
  });
  return (
    <div ref={host} class="relative">
      <CleanProofStamp impressionKey={props.impressionKey} />
    </div>
  );
});
/**
 * Short-lived ink: one canvas per effect, laid over (or under) a few rects,
 * removed as soon as it has dried. Each helper resolves to false where ink
 * is unavailable, so callers keep their plain CSS path.
 */
import { inkEngine, type InkSurface } from "./engine";
import type { InkPreset } from "./tuning";

export interface Box {
  x: number;
  y: number;
  width: number;
  height: number;
}

const PAD = 24;

function unionOf(rects: Box[]): Box {
  const left = Math.min(...rects.map((r) => r.x));
  const top = Math.min(...rects.map((r) => r.y));
  const right = Math.max(...rects.map((r) => r.x + r.width));
  const bottom = Math.max(...rects.map((r) => r.y + r.height));
  return { x: left, y: top, width: right - left, height: bottom - top };
}

/** Client rects of a DOM range, line by line, without zero-width slivers. */
export function lineRects(range: Range): DOMRect[] {
  return [...range.getClientRects()].filter((r) => r.width > 1 && r.height > 1);
}

/**
 * A canvas positioned in `host` over the given client rects, padded so ink
 * has room to spread. Rects come back relative to the canvas.
 */
async function momentSurface(
  host: HTMLElement,
  clientRects: Box[],
  preset: InkPreset,
  layer: "over" | "under",
): Promise<{ surface: InkSurface; rects: Box[] } | null> {
  if (!clientRects.length) return null;
  const engine = await inkEngine();
  if (!engine || !host.isConnected) return null;
  const hostBox = host.getBoundingClientRect();
  const union = unionOf(clientRects);
  const left = union.x - hostBox.left - host.clientLeft + host.scrollLeft - PAD;
  const top = union.y - hostBox.top - host.clientTop + host.scrollTop - PAD;
  const width = union.width + PAD * 2;
  const height = union.height + PAD * 2;

  const canvas = document.createElement("canvas");
  canvas.className = `ink-moment ink-moment--${layer}`;
  canvas.setAttribute("aria-hidden", "true");
  Object.assign(canvas.style, {
    left: `${left}px`,
    top: `${top}px`,
    width: `${width}px`,
    height: `${height}px`,
  });
  // Beneath: first in the host, so later positioned content (the stamp
  // and its die) paints over it.
  if (layer === "under") host.prepend(canvas);
  else host.appendChild(canvas);
  const surface = engine.surface(canvas, preset);
  surface.resize(width, height);
  surface.onSleep = () => {
    surface.destroy();
    canvas.remove();
  };
  const originX = union.x - PAD;
  const originY = union.y - PAD;
  return {
    surface,
    rects: clientRects.map((r) => ({
      x: r.x - originX,
      y: r.y - originY,
      width: r.width,
      height: r.height,
    })),
  };
}

export interface InkStrikeHandle {
  /** When the last line has been drawn. */
  drawn: Promise<void>;
  /** Lift the strike off with the words it struck. */
  lift(ms?: number): void;
}

/** A strike that wicks along each line, left to right. */
export async function inkStrike(
  host: HTMLElement,
  clientRects: Box[],
  color = "var(--color-vermilion)",
): Promise<InkStrikeHandle | null> {
  const moment = await momentSurface(host, clientRects, "wick", "over");
  if (!moment) return null;
  const { surface, rects } = moment;
  surface.readColors(host, color);
  let delay = 0;
  for (const r of rects) {
    const duration = Math.min(420, Math.max(160, r.width * 1.6));
    const y = r.y + r.height * 0.58;
    surface.stroke(
      { x: r.x, y },
      { x: r.x + r.width, y },
      duration,
      {
        radius: Math.max(1.3, r.height * 0.065),
        water: 0.8,
        pigment: 0.9,
        ragged: 0.5,
      },
      delay,
    );
    delay += duration * 0.85;
  }
  return {
    drawn: new Promise((resolve) => setTimeout(resolve, delay)),
    lift(ms = 180) {
      const canvas = surface.canvas;
      canvas.style.transition = `opacity ${ms}ms ease-out`;
      canvas.style.opacity = "0";
      setTimeout(() => surface.onSleep?.(), ms);
    },
  };
}

/**
 * Covers the rects with the page colour and lets ink soak up through it,
 * so the real text beneath appears as the wet front reaches it.
 */
export async function inkReveal(
  host: HTMLElement,
  clientRects: Box[],
  color = "var(--color-ink)",
): Promise<boolean> {
  const moment = await momentSurface(host, clientRects, "bleed", "over");
  if (!moment) return false;
  const { surface, rects } = moment;
  surface.readColors(host, color);
  // A line box carries the leading too; cover only the glyphs' band.
  const glyphs = rects.map((r) => ({
    x: r.x - 1,
    y: r.y + r.height * 0.14,
    width: r.width + 2,
    height: r.height * 0.74,
  }));
  surface.beginReveal(glyphs);
  glyphs.forEach((r, i) =>
    surface.bleed(r, {
      durationMs: 220 + r.width * 0.5,
      delayMs: i * 90,
      pigment: 0.012,
    }),
  );
  return true;
}

/**
 * Ink squeezed out under a round stamp: a pooled ring at its rim, and
 * droplets thrown outward from it. Drawn beneath the stamp's own mark.
 */
export async function inkStampPool(
  host: HTMLElement,
  stamp: Box,
  color = "var(--color-vermilion)",
): Promise<boolean> {
  const moment = await momentSurface(host, [stamp], "stamp", "under");
  if (!moment) return false;
  const { surface, rects } = moment;
  surface.readColors(host, color);
  const r = rects[0];
  const cx = r.x + r.width / 2;
  const cy = r.y + r.height / 2;
  const radius = Math.min(r.width, r.height) * 0.5 + 0.5;
  // The die rocks a little, so more ink escapes on one side: one unbroken
  // rim around the edge, swelling where the pressure was.
  const heavy = Math.random() * Math.PI * 2;
  const segments = 72;
  const at = (i: number) => (i / segments) * Math.PI * 2;
  for (let i = 0; i < segments; i++) {
    const lean = Math.max(0, Math.cos(at(i + 0.5) - heavy)) ** 2;
    const wobble = 0.6 * Math.sin(at(i) * 5 + heavy * 3);
    surface.drop({
      x: cx + Math.cos(at(i)) * (radius + wobble),
      y: cy + Math.sin(at(i)) * (radius + wobble),
      toX: cx + Math.cos(at(i + 1)) * (radius + wobble),
      toY: cy + Math.sin(at(i + 1)) * (radius + wobble),
      radius: 1.1 + lean * 1.7,
      water: 0.3 + lean * 0.7,
      pigment: 0.6 + lean * 0.5,
      ragged: 0.8,
    });
  }
  for (let i = 0; i < 6; i++) {
    const angle = heavy + (i - 2.5) * 0.28;
    surface.splatter({
      x: cx + Math.cos(angle) * radius,
      y: cy + Math.sin(angle) * radius,
      count: 6,
      speed: 2.4,
      heading: angle,
      arc: 0.7,
      mass: 0.3,
    });
  }
  return true;
}
