/* The same physical die prints workflow acknowledgements and verdicts.
   Only the brief press moves; the final ink stays put and remains readable. */
.ink-stamp {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  isolation: isolate;
  pointer-events: none;
}
.ink-stamp__imprint {
  position: absolute;
  inset: 0;
  display: block;
  opacity: 0.88;
}
.ink-stamp__tool {
  position: absolute;
  z-index: 3;
  top: -70%;
  left: -32.5%;
  display: block;
  width: 165%;
  max-width: none;
  height: auto;
  opacity: 0;
  object-fit: contain;
  transform-origin: 50% 82%;
  user-select: none;
}
.ink-stamp__contact-shadow {
  position: absolute;
  z-index: 2;
  inset: 26% 16% 18%;
  border-radius: 50%;
  background: #20150c;
  filter: blur(5px);
  opacity: 0;
}
.ink-stamp--pressing .ink-stamp__tool {
  animation: stamp-die-press 500ms linear both;
}
.ink-stamp--pressing .ink-stamp__imprint {
  animation: stamp-ink-settle 500ms linear both;
}
.ink-stamp--pressing .ink-stamp__contact-shadow {
  animation: stamp-contact-shadow 500ms linear both;
}

.rubric-grade-stamp {
  --stamp-rotation: -4deg;
  position: relative;
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  color: var(--color-ink);
  transform: rotate(var(--stamp-rotation));
  transform-origin: center;
  isolation: isolate;
}
.rubric-grade-stamp__mark {
  position: absolute;
  inset: 0;
  background: currentColor;
  -webkit-mask: var(--rubric-stamp-image) center / contain no-repeat;
  mask: var(--rubric-stamp-image) center / contain no-repeat;
}
.rubric-grade-stamp--compact {
  width: 5.5rem;
  height: 5.5rem;
}
.rubric-grade-stamp--report {
  width: 9rem;
  height: 9rem;
}
.rubric-grade-stamp--a {
  --stamp-rotation: -5deg;
}
.rubric-grade-stamp--b {
  --stamp-rotation: 3deg;
}
.rubric-grade-stamp--c {
  --stamp-rotation: -2deg;
}
.rubric-grade-stamp--revise {
  --stamp-rotation: 4deg;
}
.rubric-grade-stamp--animated {
  z-index: 2;
}
/* Give the handle room above the compact mark, without affecting layout. */
.rubric-proof:has(.rubric-grade-stamp--animated) {
  overflow: visible;
}

.workflow-stamp {
  position: relative;
  display: block;
  width: min(15rem, 65vw);
  aspect-ratio: 1;
  color: var(--color-vermilion);
  transform: rotate(-4deg);
  flex: 0 0 auto;
  pointer-events: none;
}
.workflow-stamp__mark {
  position: absolute;
  inset: 0;
  background: currentColor;
  -webkit-mask: var(--workflow-stamp-image) center / contain no-repeat;
  mask: var(--workflow-stamp-image) center / contain no-repeat;
}
.dossier-filed-confirmation__paper:has(.workflow-stamp) {
  border: 0;
  box-shadow: none;
  background: transparent;
  padding: 0;
  text-transform: none;
  animation: none;
}
.dossier-filed-confirmation__paper .workflow-stamp {
  margin-block: -2rem;
}

@keyframes rubric-proof-settle {
  from {
    filter: contrast(0.96) brightness(1.025);
    transform: translateY(-4px) scaleY(0.992);
  }
  to {
    filter: contrast(1) brightness(1);
    transform: translateY(0) scaleY(1);
  }
}

/* Approach, contact at 160ms, a brief compression, then a clean lift. */
@keyframes stamp-die-press {
  0% {
    opacity: 0;
    transform: translate(14%, -48%) rotate(-10deg) scale(1.12);
    animation-timing-function: cubic-bezier(0.55, 0, 0.85, 0.55);
  }
