/** Accepting a proposed edit: struck words give way to the new ones. */
export const AcceptDemo = component$<{ ink: boolean; replay: number }>(
  (props) => {
    const host = useSignal<HTMLDivElement>();
    const target = useSignal<HTMLSpanElement>();
    const stamp = useSignal(0);
    const state = useStore({ accepted: false });
    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(async ({ track, cleanup }) => {
      track(() => props.replay);
      const el = host.value;
      const span = target.value;
      if (!el || !span) return;
      let stopped = false;
      cleanup(() => {
        stopped = true;
      });
      // Resolves false once a replay has superseded this run.
      const wait = (ms: number) =>
        new Promise<boolean>((resolve) =>
          setTimeout(() => resolve(!stopped), ms),
        );
      state.accepted = false;
      stamp.value = 0;
      span.style.opacity = "";
      span.textContent = "voted in favour of approving";
      if (!(await wait(700))) return;
      if (props.ink) {
        const range = document.createRange();
        range.selectNodeContents(span);
        const strike = await inkStrike(el, lineRects(range));
        if (strike) {
          await strike.drawn;
          if (!(await wait(260))) return strike.lift(0);
          // The struck words lift away with their strike.
          span.style.transition = "opacity 180ms ease-out";
          span.style.opacity = "0";
          strike.lift(180);
          await wait(200);
          span.style.transition = "";
          span.style.opacity = "";
          if (stopped) return;
        }
      }
      state.accepted = true;
      span.textContent = "approved";
      stamp.value = props.replay + 1;
      if (props.ink) {
        await new Promise((r) => requestAnimationFrame(r));
        const range = document.createRange();
        range.selectNodeContents(span);
        await inkReveal(el, lineRects(range));
      }
    });
    return (
      <div
        ref={host}
        class="paper-sheet relative min-h-[9.5rem] overflow-hidden px-6 py-5"
      >
        <p
          class="text-[1.125rem] leading-[1.8]"
          style="font-family: var(--font-serif)"
        >
          After a long night the committee{" "}
          <span ref={target} class={{ "twyne-suggestion": !state.accepted }}>
            voted in favour of approving
          </span>{" "}
          the measure.
        </p>
        {stamp.value > 0 && (
          <div
            key={stamp.value}
            class="ink-lab-stamp pointer-events-none absolute right-3 top-1"
          >
            <WorkflowStamp kind="revised" impressionKey={stamp.value} />
          </div>
        )}
      </div>
    );
  },
);

