/**
 * Wet ink on WebGPU. One device, one set of WGSL pipelines and one fiber
 * sheet are shared; every place ink appears gets its own canvas surface
 * with its own field. All awake surfaces step and present in a single
 * submission per frame, and a surface with nothing wet on it costs nothing.
 *
 * The simulation never touches the text it sits under or over, so input,
 * selection and screen readers are unaffected by anything here.
 */
import commonWgsl from "./wgsl/common.wgsl?raw";
import fibersWgsl from "./wgsl/fibers.wgsl?raw";
import renderWgsl from "./wgsl/render.wgsl?raw";
import simWgsl from "./wgsl/sim.wgsl?raw";
import splatterWgsl from "./wgsl/splatter.wgsl?raw";
import {
  INK_PRESETS,
  parseComputedRgb,
  relativeLuminance,
  srgbToLinear,
  type InkPreset,
  type InkTuning,
} from "./tuning";

const FIBER_SIZE = 512;
const MAX_DROPS = 64;
const MAX_DROPLETS = 512;
const DROP_FLOATS = 8;
const DROPLET_FLOATS = 8;
const MASS_UNITS = 1024;
const MAX_DPR = 2;

export class InkEngine {
  private readonly awake = new Set<InkSurface>();
  private readonly surfaces = new Set<InkSurface>();
  private frame = 0;
  private lastTick = 0;
  private dead = false;
  private timestamps: Timestamps | null = null;
  /** Collect GPU timings; the lab turns this on. */
  measure = false;
  private quiet = false;
  readonly stats: InkStats;

  private constructor(
    readonly device: GPUDevice,
    readonly format: GPUTextureFormat,
    readonly fibers: GPUTexture,
    readonly simPipeline: GPUComputePipeline,
    readonly splatterPipeline: GPUComputePipeline,
    readonly renderPipeline: GPURenderPipeline,
    readonly fieldSampler: GPUSampler,
    readonly fiberSampler: GPUSampler,
    adapter: string,
  ) {
    this.stats = {
      adapter,
      fps: 0,
      cpuMs: 0,
      gpuMs: null,
      awake: 0,
      economy: false,
    };
    if (device.features.has("timestamp-query")) {
      this.timestamps = {
        set: device.createQuerySet({ type: "timestamp", count: 2 }),
        resolve: device.createBuffer({
          size: 16,
          usage: GPUBufferUsage.QUERY_RESOLVE | GPUBufferUsage.COPY_SRC,
        }),
        read: device.createBuffer({
          size: 16,
          usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
        }),
        pending: false,
      };
    }
    void device.lost.then((info) => {
      this.dead = true;
      enginePromise = null;
      if (info.reason !== "destroyed") {
        console.warn("[twyne:ink] device lost", info.message);
      }
      for (const surface of this.surfaces) surface.markLost();
    });
  }

  static async create(): Promise<InkEngine | null> {
    const adapter = await navigator.gpu.requestAdapter({
      powerPreference: "low-power",
    });
    if (!adapter) return null;
    const features: GPUFeatureName[] = adapter.features.has("timestamp-query")
      ? ["timestamp-query"]
      : [];
    const device = await adapter.requestDevice({
      label: "twyne ink",
      requiredFeatures: features,
    });
    const format = navigator.gpu.getPreferredCanvasFormat();
    const [fiberModule, simModule, splatterModule, renderModule] =
      await Promise.all([
        checkedModule(device, "ink fibers", fibersWgsl),
        checkedModule(device, "ink sim", simWgsl),
        checkedModule(device, "ink splatter", splatterWgsl),
        checkedModule(device, "ink render", renderWgsl),
      ]);
    const [fiberPipeline, simPipeline, splatterPipeline, renderPipeline] =
      await Promise.all([
        device.createComputePipelineAsync({
          label: "ink fibers",
          layout: "auto",
          compute: { module: fiberModule, entryPoint: "main" },
        }),
        device.createComputePipelineAsync({
          label: "ink sim",
          layout: "auto",
          compute: { module: simModule, entryPoint: "main" },
        }),
        device.createComputePipelineAsync({
          label: "ink splatter",
          layout: "auto",
          compute: { module: splatterModule, entryPoint: "main" },
        }),
        device.createRenderPipelineAsync({
          label: "ink render",
          layout: "auto",
          vertex: { module: renderModule, entryPoint: "vs" },
          fragment: {
            module: renderModule,
            entryPoint: "fs",
            targets: [{ format }],
          },
          primitive: { topology: "triangle-list" },
        }),
      ]);

    const fibers = device.createTexture({
      label: "ink fiber sheet",
      size: [FIBER_SIZE, FIBER_SIZE],
      format: "rgba8unorm",
      usage: GPUTextureUsage.STORAGE_BINDING | GPUTextureUsage.TEXTURE_BINDING,
    });
    const fiberParams = device.createBuffer({
      size: 16,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });
    const raw = new ArrayBuffer(16);
    new Uint32Array(raw, 0, 1)[0] = FIBER_SIZE;
    // Strand cell, grain angle (nearly level, as a sheet comes off the
    // wire), and how far strands stray from it.
    new Float32Array(raw, 4, 3).set([16, -0.06, 1.1]);
    device.queue.writeBuffer(fiberParams, 0, raw);
    const encoder = device.createCommandEncoder({ label: "ink fibers" });
    const pass = encoder.beginComputePass();
    pass.setPipeline(fiberPipeline);
    pass.setBindGroup(
      0,
      device.createBindGroup({
        layout: fiberPipeline.getBindGroupLayout(0),
        entries: [
          { binding: 0, resource: fibers.createView() },
          { binding: 1, resource: { buffer: fiberParams } },
        ],
      }),
    );
    pass.dispatchWorkgroups(FIBER_SIZE / 8, FIBER_SIZE / 8);
    pass.end();
    device.queue.submit([encoder.finish()]);
    fiberParams.destroy();

    const info = adapter.info;
    return new InkEngine(
      device,
      format,
      fibers,
      simPipeline,
      splatterPipeline,
      renderPipeline,
      device.createSampler({ magFilter: "linear", minFilter: "linear" }),
      device.createSampler({
        magFilter: "linear",
        minFilter: "linear",
        addressModeU: "repeat",
        addressModeV: "repeat",
      }),
      [info.vendor, info.architecture].filter(Boolean).join(" ") || "webgpu",
    );
  }

  get lost(): boolean {
    return this.dead;
  }

  /** A canvas of ink. Size it with `resize` before dropping anything. */
  surface(
    canvas: HTMLCanvasElement,
    tuning: InkPreset | InkTuning = "typing",
  ): InkSurface {
    const surface = new InkSurface(
      this,
      canvas,
      typeof tuning === "string" ? { ...INK_PRESETS[tuning] } : { ...tuning },
    );
    this.surfaces.add(surface);
    return surface;
  }

  /**
   * Hold the canvases still for the coming frame. A canvas presented in the
   * same frame as a typed letter delays that letter's paint by a frame, so
   * the letter goes first and the ink catches up on the next.
   */
  yieldFrame(): void {
    this.quiet = true;
  }

  /** @internal */
  forget(surface: InkSurface): void {
    this.surfaces.delete(surface);
    this.awake.delete(surface);
  }

  /** @internal */
  wake(surface: InkSurface): void {
    if (this.dead) return;
    const wasIdle = this.awake.size === 0;
    this.awake.add(surface);
    if (wasIdle) {
      this.lastTick = 0;
      requestAnimationFrame(this.tick);
    }
  }

  private readonly tick = (now: number): void => {
    if (this.dead || this.awake.size === 0) return;
    const started = performance.now();
    const economy = economyHolds > 0;
    const present = !this.quiet;
    this.quiet = false;
    const timed =
      present &&
      this.measure &&
      this.timestamps !== null &&
      !this.timestamps.pending;
    const encoder = this.device.createCommandEncoder({ label: "ink frame" });
    const compute = encoder.beginComputePass(
      timed
        ? {
            timestampWrites: {
              querySet: this.timestamps!.set,
              beginningOfPassWriteIndex: 0,
            },
          }
        : undefined,
    );
    const surfaces = [...this.awake];
    for (const surface of surfaces) surface.step(compute, now, economy);
    compute.end();
    if (present)
      surfaces.forEach((surface, i) =>
        surface.render(
          encoder,
          now,
          timed && i === surfaces.length - 1 ? this.timestamps!.set : null,
        ),
      );
    if (timed) {
      const t = this.timestamps!;
      encoder.resolveQuerySet(t.set, 0, 2, t.resolve, 0);
      encoder.copyBufferToBuffer(t.resolve, 0, t.read, 0, 16);
    }
    this.device.queue.submit([encoder.finish()]);
    if (timed) this.readTimestamps();

    // A surface's last frame clears its canvas, so it only sleeps on a
    // frame that presented.
    for (const surface of present ? surfaces : []) {
      if (!surface.asleep(now)) continue;
      this.awake.delete(surface);
      surface.onSleep?.();
    }
    const cpu = performance.now() - started;
    const interval = this.lastTick ? now - this.lastTick : 0;
    this.lastTick = now;
    this.frame++;
    this.stats.cpuMs = ema(this.stats.cpuMs, cpu, this.frame);
    if (interval > 0) {
      this.stats.fps = ema(this.stats.fps, 1000 / interval, this.frame);
    }
    this.stats.awake = this.awake.size;
    this.stats.economy = economy;
    if (this.awake.size) requestAnimationFrame(this.tick);
  };

  private readTimestamps(): void {
    const t = this.timestamps!;
    t.pending = true;
    void t.read
      .mapAsync(GPUMapMode.READ)
      .then(() => {
        const [begin, end] = new BigUint64Array(t.read.getMappedRange());
        if (end > begin) {
          const ms = Number(end - begin) / 1e6;
          this.stats.gpuMs = ema(this.stats.gpuMs ?? ms, ms, this.frame);
        }
        t.read.unmap();
      })
      .catch(() => {})
      .finally(() => {
        t.pending = false;
      });
  }
}

function ema(previous: number, next: number, frame: number): number {
  const k = frame < 10 ? 0.5 : 0.08;
  return previous + (next - previous) * k;
}

