  /** Dry everything at once. */
  clear(): void {
    this.pending = [];
    this.scheduled = [];
    this.revealing = false;
    this.wipe = true;
    this.touch();
  }

  destroy(): void {
    if (this.dead) return;
    this.dead = true;
    this.engine.forget(this);
    this.fields?.forEach((t) => t.destroy());
    for (const buffer of [
      this.splat,
      this.simParams,
      this.quietParams,
      this.renderParams,
      this.dropBuffer,
      this.droplets,
      this.splatterParams,
    ]) {
      buffer?.destroy();
    }
    try {
      this.context.unconfigure();
    } catch {
      // Already gone with the device.
    }
  }

  /** @internal */
  markLost(): void {
    this.dead = true;
  }

  private touch(): void {
    this.lastActivity = performance.now();
    this.engine.wake(this);
  }

  private allocate(): void {
    const device = this.engine.device;
    this.fields?.forEach((t) => t.destroy());
    this.splat?.destroy();
    const make = (label: string) =>
      device.createTexture({
        label,
        size: [this.cols, this.rows],
        format: "rgba16float",
        usage:
          GPUTextureUsage.STORAGE_BINDING |
          GPUTextureUsage.TEXTURE_BINDING |
          GPUTextureUsage.COPY_DST,
      });
    this.fields = [make("ink field a"), make("ink field b")];
    this.current = 0;
    this.splat = device.createBuffer({
      size: this.cols * this.rows * 4,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    const views = this.fields.map((t) => t.createView());
    const simLayout = this.engine.simPipeline.getBindGroupLayout(0);
    const fiberView = this.engine.fibers.createView();
    this.simGroups = [0, 1].map((from) =>
      [this.quietParams, this.simParams].map((params) =>
        device.createBindGroup({
          layout: simLayout,
          entries: [
            { binding: 0, resource: views[from] },
            { binding: 1, resource: views[1 - from] },
            { binding: 2, resource: fiberView },
            { binding: 3, resource: { buffer: params } },
            { binding: 4, resource: { buffer: this.dropBuffer } },
            { binding: 5, resource: { buffer: this.splat! } },
          ],
        }),
      ),
    );
    const renderLayout = this.engine.renderPipeline.getBindGroupLayout(0);
    this.renderGroups = [0, 1].map((i) =>
      device.createBindGroup({
        layout: renderLayout,
        entries: [
          { binding: 0, resource: views[i] },
          { binding: 1, resource: this.engine.fieldSampler },
          { binding: 2, resource: fiberView },
          { binding: 3, resource: this.engine.fiberSampler },
          { binding: 4, resource: { buffer: this.renderParams } },
        ],
      }),
    );
    this.splatterGroup = device.createBindGroup({
      layout: this.engine.splatterPipeline.getBindGroupLayout(0),
      entries: [
        { binding: 0, resource: { buffer: this.droplets } },
        { binding: 1, resource: { buffer: this.splat } },
        { binding: 2, resource: { buffer: this.splatterParams } },
      ],
    });
    // Old droplets would land in the wrong place on a new grid.
    device.queue.writeBuffer(
      this.droplets,
      0,
      new Float32Array(MAX_DROPLETS * DROPLET_FLOATS),
    );
  }

  private writeSimParams(buffer: GPUBuffer, dropCount: number): void {
    const t = this.tuning;
    const raw = new ArrayBuffer(64);
    const u = new Uint32Array(raw);
    const f = new Float32Array(raw);
    u[0] = this.cols;
    u[1] = this.rows;
    u[2] = this.fiberOffset[0];
    u[3] = this.fiberOffset[1];
    f[4] = t.flow;
    f[5] = t.anisotropy;
    f[6] = t.absorb;
    f[7] = t.evaporation;
    f[8] = t.edgeRing;
    f[9] = t.fade;
    f[10] = t.pin;
    f[11] = t.revealAt;
    u[12] = dropCount;
    f[13] = 1 / MASS_UNITS;
    f[14] = t.cellPx;
    f[15] = t.carry;
    this.engine.device.queue.writeBuffer(buffer, 0, raw);
  }

  /** @internal */
  step(pass: GPUComputePassEncoder, now: number, economy: boolean): void {
    if (this.dead || !this.fields) return;
    const device = this.engine.device;
    if (this.wipe) {
      this.wipe = false;
      const start =
        this.initialField ?? new Uint16Array(this.cols * this.rows * 4);
      this.initialField = null;
      for (const field of this.fields) {
        device.queue.writeTexture(
          { texture: field },
          start,
          { bytesPerRow: this.cols * 8 },
          [this.cols, this.rows],
        );
      }
      device.queue.writeBuffer(
        this.splat!,
        0,
        new Uint32Array(this.cols * this.rows),
      );
    }

    if (this.scheduled.length) {
      const due = this.scheduled.filter((s) => s.at <= now);
      if (due.length) {
        this.scheduled = this.scheduled.filter((s) => s.at > now);
        this.pending.push(...due.map((s) => s.drop));
        this.lastActivity = now;
      }
    }
    const drops = this.pending.splice(0, MAX_DROPS);
    const cell = this.tuning.cellPx;
    drops.forEach((d, i) => {
      const o = i * DROP_FLOATS;
      this.dropData[o] = d.x / cell;
      this.dropData[o + 1] = d.y / cell;
      this.dropData[o + 2] = (d.toX ?? d.x) / cell;
      this.dropData[o + 3] = (d.toY ?? d.y) / cell;
      this.dropData[o + 4] = Math.max(d.radius / cell, 0.75);
      this.dropData[o + 5] = d.water;
      this.dropData[o + 6] = d.pigment;
      this.dropData[o + 7] = d.ragged ?? 0.4;
    });
    if (drops.length) {
      device.queue.writeBuffer(
        this.dropBuffer,
        0,
        this.dropData,
        0,
        drops.length * DROP_FLOATS,
      );
    }
    this.writeSimParams(this.simParams, drops.length);
    this.writeSimParams(this.quietParams, 0);

    if (now < this.dropletsUntil) {
      const raw = new ArrayBuffer(32);
      const u = new Uint32Array(raw);
      const f = new Float32Array(raw);
      u[0] = this.cols;
      u[1] = this.rows;
      u[2] = MAX_DROPLETS;
      f[3] = 0.045; // gravity, in launch heights per frame²
      f[4] = 0.9; // air drag
      device.queue.writeBuffer(this.splatterParams, 0, raw);
      pass.setPipeline(this.engine.splatterPipeline);
      pass.setBindGroup(0, this.splatterGroup!);
      pass.dispatchWorkgroups(Math.ceil(MAX_DROPLETS / 64));
    }

    const substeps = economy ? 1 : this.tuning.substeps;
    pass.setPipeline(this.engine.simPipeline);
    for (let k = 0; k < substeps; k++) {
      const withDrops = k === 0 && drops.length > 0 ? 1 : 0;
      pass.setBindGroup(0, this.simGroups[this.current][withDrops]);
      pass.dispatchWorkgroups(
        Math.ceil(this.cols / 8),
        Math.ceil(this.rows / 8),
      );
      this.current = 1 - this.current;
    }
  }

  /** @internal */
  render(
    encoder: GPUCommandEncoder,
    now: number,
    timestamps: GPUQuerySet | null,
  ): void {
    if (this.dead || !this.fields) return;
    const sleeping = this.asleep(now);
    const raw = new Float32Array(24);
    raw.set(this.paper.map(srgbToLinear), 0);
    raw[3] = this.tuning.strength;
    raw.set(this.ink.map(srgbToLinear), 4);
    raw[7] = this.tuning.sheen;
    raw.set(this.cover.map(srgbToLinear), 8);
    raw[11] = this.revealing && !sleeping ? 1 : 0;
    raw[12] = 1 / this.cols;
    raw[13] = 1 / this.rows;
    raw[14] = this.cssWidth / FIBER_SIZE;
    raw[15] = this.cssHeight / FIBER_SIZE;
    raw[16] = this.fiberOffset[0] / FIBER_SIZE;
    raw[17] = this.fiberOffset[1] / FIBER_SIZE;
    raw[18] = this.dark ? 1 : 0;
    raw[19] = this.tuning.grain;
    // A cover lifts by the end of the surface's life even where ink never
    // reached, so nothing beneath stays hidden.
    const age = now - this.revealStarted;
    const life = this.tuning.lifetimeMs;
    raw[20] = Math.min(1, Math.max(0, (age - life * 0.45) / (life * 0.35)));
    this.engine.device.queue.writeBuffer(this.renderParams, 0, raw);

    const pass = encoder.beginRenderPass({
      colorAttachments: [
        {
          view: this.context.getCurrentTexture().createView(),
          clearValue: { r: 0, g: 0, b: 0, a: 0 },
          loadOp: "clear",
          storeOp: "store",
        },
      ],
      timestampWrites: timestamps
        ? { querySet: timestamps, endOfPassWriteIndex: 1 }
        : undefined,
    });
    // The last frame of a surface only clears it.
    if (!sleeping) {
      pass.setPipeline(this.engine.renderPipeline);
      pass.setBindGroup(0, this.renderGroups[this.current]);
      pass.draw(3);
    }
    pass.end();
    if (this.revealing && this.onPresented) {
      const presented = this.onPresented;
      this.onPresented = null;
      requestAnimationFrame(() => presented());
    }
    if (sleeping) {
      this.revealing = false;
      this.wipe = true;
    }
  }

  /** @internal */
  asleep(now: number): boolean {
    return (
      this.dead ||
      (this.pending.length === 0 &&
        this.scheduled.length === 0 &&
        now > this.dropletsUntil &&
        now - this.lastActivity > this.tuning.lifetimeMs)
    );
  }
}

