/**
 * Short-lived ink: one canvas per effect, laid over (or under) a few rects,
 * removed as soon as it has dried. Each helper resolves to false where ink
 * is unavailable, so callers keep their plain CSS path.
 */
import { inkEngine, type InkSurface } from "./engine";
import type { InkPreset } from "./tuning";

export interface Box {
  x: number;
  y: number;
  width: number;
  height: number;
}

const PAD = 24;

function unionOf(rects: Box[]): Box {
  const left = Math.min(...rects.map((r) => r.x));
  const top = Math.min(...rects.map((r) => r.y));
  const right = Math.max(...rects.map((r) => r.x + r.width));
  const bottom = Math.max(...rects.map((r) => r.y + r.height));
  return { x: left, y: top, width: right - left, height: bottom - top };
}

/** Client rects of a DOM range, line by line, without zero-width slivers. */
export function lineRects(range: Range): DOMRect[] {
  return [...range.getClientRects()].filter((r) => r.width > 1 && r.height > 1);
}

/**
 * A canvas positioned in `host` over the given client rects, padded so ink
 * has room to spread. Rects come back relative to the canvas.
 */
async function momentSurface(
  host: HTMLElement,
  clientRects: Box[],
  preset: InkPreset,
  layer: "over" | "under",
): Promise<{ surface: InkSurface; rects: Box[] } | null> {
  if (!clientRects.length) return null;
  const engine = await inkEngine();
  if (!engine || !host.isConnected) return null;
  const hostBox = host.getBoundingClientRect();
  const union = unionOf(clientRects);
  const left = union.x - hostBox.left - host.clientLeft + host.scrollLeft - PAD;
  const top = union.y - hostBox.top - host.clientTop + host.scrollTop - PAD;
  const width = union.width + PAD * 2;
  const height = union.height + PAD * 2;

  const canvas = document.createElement("canvas");
  canvas.className = `ink-moment ink-moment--${layer}`;
  canvas.setAttribute("aria-hidden", "true");
  Object.assign(canvas.style, {
    left: `${left}px`,
    top: `${top}px`,
    width: `${width}px`,
    height: `${height}px`,
  });
  // Beneath: first in the host, so later positioned content (the stamp
  // and its die) paints over it.
  if (layer === "under") host.prepend(canvas);
  else host.appendChild(canvas);
  const surface = engine.surface(canvas, preset);
  surface.resize(width, height);
  surface.onSleep = () => {
    surface.destroy();
    canvas.remove();
  };
  const originX = union.x - PAD;
  const originY = union.y - PAD;
  return {
    surface,
    rects: clientRects.map((r) => ({
      x: r.x - originX,
      y: r.y - originY,
      width: r.width,
      height: r.height,
    })),
  };
}

export interface InkStrikeHandle {
  /** When the last line has been drawn. */
  drawn: Promise<void>;
  /** Lift the strike off with the words it struck. */
  lift(ms?: number): void;
}

/** A strike that wicks along each line, left to right. */
export async function inkStrike(
  host: HTMLElement,
  clientRects: Box[],
  color = "var(--color-vermilion)",
): Promise<InkStrikeHandle | null> {
  const moment = await momentSurface(host, clientRects, "wick", "over");
  if (!moment) return null;
  const { surface, rects } = moment;
  surface.readColors(host, color);
  let delay = 0;
  for (const r of rects) {
    const duration = Math.min(420, Math.max(160, r.width * 1.6));
    const y = r.y + r.height * 0.58;
    surface.stroke(
      { x: r.x, y },
      { x: r.x + r.width, y },
      duration,
      {
        radius: Math.max(1.3, r.height * 0.065),
        water: 0.8,
        pigment: 0.9,
        ragged: 0.5,
      },
      delay,
    );
    delay += duration * 0.85;
  }
  return {
    drawn: new Promise((resolve) => setTimeout(resolve, delay)),
    lift(ms = 180) {
      const canvas = surface.canvas;
      canvas.style.transition = `opacity ${ms}ms ease-out`;
      canvas.style.opacity = "0";
      setTimeout(() => surface.onSleep?.(), ms);
    },
  };
}

