// Smooth value noise on a lattice that wraps every `period` cells, so the
// fiber sheet tiles without a seam.
fn tiledNoise(p: vec2f, period: f32) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = hash21(i - period * floor(i / period));
  let b = hash21((i + vec2f(1.0, 0.0)) - period * floor((i + vec2f(1.0, 0.0)) / period));
  let c = hash21((i + vec2f(0.0, 1.0)) - period * floor((i + vec2f(0.0, 1.0)) / period));
  let d = hash21((i + vec2f(1.0, 1.0)) - period * floor((i + vec2f(1.0, 1.0)) / period));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn segmentDistance(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
  return length(pa - ba * h);
}

// Single-constant Kubelka–Munk: pigment absorbs and scatters, so layering
// darkens the way ink on paper does instead of greying like alpha.
fn kmAbsorption(r: vec3f) -> vec3f {
  let c = clamp(r, vec3f(0.002), vec3f(0.998));
  return (1.0 - c) * (1.0 - c) / (2.0 * c);
}

fn kmReflectance(ks: vec3f) -> vec3f {
  return 1.0 + ks - sqrt(ks * ks + 2.0 * ks);
}

