18	function unionOf(rects: Box[]): Box {
19	  const left = Math.min(...rects.map((r) => r.x));
20	  const top = Math.min(...rects.map((r) => r.y));
21	  const right = Math.max(...rects.map((r) => r.x + r.width));
22	  const bottom = Math.max(...rects.map((r) => r.y + r.height));
23	  return { x: left, y: top, width: right - left, height: bottom - top };
24	}
