31	/**
32	 * A canvas positioned in `host` over the given client rects, padded so ink
33	 * has room to spread. Rects come back relative to the canvas.
34	 */
35	async function momentSurface(
36	  host: HTMLElement,
37	  clientRects: Box[],
38	  preset: InkPreset,
39	  layer: "over" | "under",
40	): Promise<{ surface: InkSurface; rects: Box[] } | null> {
41	  if (!clientRects.length) return null;
42	  const engine = await inkEngine();
43	  if (!engine || !host.isConnected) return null;
44	  const hostBox = host.getBoundingClientRect();
45	  const union = unionOf(clientRects);
46	  const left = union.x - hostBox.left - host.clientLeft + host.scrollLeft - PAD;
47	  const top = union.y - hostBox.top - host.clientTop + host.scrollTop - PAD;
48	  const width = union.width + PAD * 2;
49	  const height = union.height + PAD * 2;
50	
51	  const canvas = document.createElement("canvas");
52	  canvas.className = `ink-moment ink-moment--${layer}`;
53	  canvas.setAttribute("aria-hidden", "true");
54	  Object.assign(canvas.style, {
55	    left: `${left}px`,
56	    top: `${top}px`,
57	    width: `${width}px`,
58	    height: `${height}px`,
59	  });
60	  // Beneath: first in the host, so later positioned content (the stamp
61	  // and its die) paints over it.
62	  if (layer === "under") host.prepend(canvas);
63	  else host.appendChild(canvas);
64	  const surface = engine.surface(canvas, preset);
65	  surface.resize(width, height);
66	  surface.onSleep = () => {
67	    surface.destroy();
68	    canvas.remove();
69	  };
70	  const originX = union.x - PAD;
71	  const originY = union.y - PAD;
72	  return {
73	    surface,
74	    rects: clientRects.map((r) => ({
75	      x: r.x - originX,
76	      y: r.y - originY,
77	      width: r.width,
78	      height: r.height,
79	    })),
80	  };
81	}
