91	export async function inkStrike(
92	  host: HTMLElement,
93	  clientRects: Box[],
94	  color = "var(--color-vermilion)",
95	): Promise<InkStrikeHandle | null> {
96	  const moment = await momentSurface(host, clientRects, "wick", "over");
97	  if (!moment) return null;
98	  const { surface, rects } = moment;
99	  surface.readColors(host, color);
100	  let delay = 0;
101	  for (const r of rects) {
102	    const duration = Math.min(420, Math.max(160, r.width * 1.6));
103	    const y = r.y + r.height * 0.58;
104	    surface.stroke(
