160	/**
161	 * Ink squeezed out under a round stamp: a pooled ring at its rim, and
162	 * droplets thrown outward from it. Drawn beneath the stamp's own mark.
163	 */
164	export async function inkStampPool(
165	  host: HTMLElement,
166	  stamp: Box,
167	  color = "var(--color-vermilion)",
168	): Promise<boolean> {
169	  const moment = await momentSurface(host, [stamp], "stamp", "under");
170	  if (!moment) return false;
171	  const { surface, rects } = moment;
172	  surface.readColors(host, color);
173	  const r = rects[0];
174	  const cx = r.x + r.width / 2;
175	  const cy = r.y + r.height / 2;
176	  const radius = Math.min(r.width, r.height) * 0.5 + 0.5;
177	  // The die rocks a little, so more ink escapes on one side: one unbroken
178	  // rim around the edge, swelling where the pressure was.
179	  const heavy = Math.random() * Math.PI * 2;
180	  const segments = 72;
181	  const at = (i: number) => (i / segments) * Math.PI * 2;
182	  for (let i = 0; i < segments; i++) {
183	    const lean = Math.max(0, Math.cos(at(i + 0.5) - heavy)) ** 2;
184	    const wobble = 0.6 * Math.sin(at(i) * 5 + heavy * 3);
185	    surface.drop({
186	      x: cx + Math.cos(at(i)) * (radius + wobble),
187	      y: cy + Math.sin(at(i)) * (radius + wobble),
188	      toX: cx + Math.cos(at(i + 1)) * (radius + wobble),
189	      toY: cy + Math.sin(at(i + 1)) * (radius + wobble),
190	      radius: 1.1 + lean * 1.7,
191	      water: 0.3 + lean * 0.7,
192	      pigment: 0.6 + lean * 0.5,
193	      ragged: 0.8,
194	    });
195	  }
196	  for (let i = 0; i < 6; i++) {
197	    const angle = heavy + (i - 2.5) * 0.28;
198	    surface.splatter({
199	      x: cx + Math.cos(angle) * radius,
200	      y: cy + Math.sin(angle) * radius,
201	      count: 6,
202	      speed: 2.4,
203	      heading: angle,
204	      arc: 0.7,
205	      mass: 0.3,
206	    });
207	  }
208	  return true;
209	}
