// A rubber stamp's print. Nothing flows: the die meets the page once, and
// ink transfers wherever rubber and paper touch. How much depends on the
// pressure there (a hand always leans one way), the paper's tooth (a light
// press inks only its high points) and the film on the rubber (never even,
// with pinholes where it beaded). Squeezed rubber pushes ink to its edges,
// so outlines print darker, and a little fatter on the heavy side. Fresh
// ink sits dark and glossy for a moment, then dries matte.

struct StampParams {
  paper: vec3f,
  dark: f32,
  ink: vec3f,
  // Milliseconds since the die first touched; negative before.
  time: f32,
  // Unit vector toward the side pressed hardest.
  heavy: vec2f,
  lean: f32,
  load: f32,
  // Canvas size in CSS pixels.
  size: vec2f,
  seed: vec2f,
  fiberOffset: vec2f,
  ratio: f32,
  _pad: f32,
}

@group(0) @binding(0) var die: texture_2d<f32>;
@group(0) @binding(1) var dieSampler: sampler;
@group(0) @binding(2) var fibers: texture_2d<f32>;
@group(0) @binding(3) var fiberSampler: sampler;
@group(0) @binding(4) var<uniform> params: StampParams;

// The die rocks down over this long, then lifts; the print is set by then.
const ROCK_MS = 70.0;
const LIFT_MS = 100.0;
// From lift to matte.
const DRY_MS = 900.0;

struct VertexOut {
  @builtin(position) position: vec4f,
  @location(0) uv: vec2f,
}

@vertex
fn vs(@builtin(vertex_index) i: u32) -> VertexOut {
  let corner = vec2f(f32((i << 1u) & 2u), f32(i & 2u));
  var out: VertexOut;
  out.position = vec4f(corner * 2.0 - 1.0, 0.0, 1.0);
  out.uv = vec2f(corner.x, 1.0 - corner.y);
  return out;
}

// The rubber face, softened by `r` CSS pixels. A little softening closes
// the specks baked into the die art and rounds its edges as pressed rubber
// does; more of it says how near an edge a point is.
fn face(uv: vec2f, r: f32) -> f32 {
  let d = r * params.ratio / vec2f(textureDimensions(die));
  let dx = vec2f(d.x, 0.0);
  let dy = vec2f(0.0, d.y);
  var sum = textureSample(die, dieSampler, uv).a * 4.0;
  sum += (textureSample(die, dieSampler, uv + dx).a
    + textureSample(die, dieSampler, uv - dx).a
    + textureSample(die, dieSampler, uv + dy).a
    + textureSample(die, dieSampler, uv - dy).a) * 2.0;
  sum += textureSample(die, dieSampler, uv + dx + dy).a
    + textureSample(die, dieSampler, uv + dx - dy).a
    + textureSample(die, dieSampler, uv - dx + dy).a
    + textureSample(die, dieSampler, uv - dx - dy).a;
  return sum / 16.0;
}

@fragment
fn fs(in: VertexOut) -> @location(0) vec4f {
  let px = in.uv * params.size;
  let body = face(in.uv, 0.8);
  let wide = face(in.uv, 2.6);
  let fiber = textureSample(fibers, fiberSampler, px / vec2f(textureDimensions(fibers)) + params.fiberOffset);

  // Pressure falls away from the heavy side, and the rubber is never quite
  // flat. The die rocks down from the heavy side, so contact sweeps across.
  let centre = (px - params.size * 0.5) / max(params.size.x, params.size.y);
  let side = clamp(dot(centre, params.heavy) * 2.0, -1.0, 1.0);
  let lumpy = tiledNoise(px / 38.0 + params.seed, 1024.0);
  let pressure = clamp(1.0 - params.lean * (0.55 - 0.45 * side) + (lumpy - 0.5) * 0.3, 0.15, 1.1);
  let reached = params.lean * ROCK_MS * (1.0 - side) * 0.5;
  let force = pressure * smoothstep(reached, reached + 35.0, min(params.time, LIFT_MS));

  // The outline spreads under a heavier press, and the fibers rag it.
  let edge = 0.5 - 0.14 * force + (fiber.r - 0.5) * 0.22;
  let aa = max(fwidth(body), 1e-4) * 0.75;
  let shape = smoothstep(edge - aa, edge + aa, body);
  // Squeezed ink gathers along the inside of every edge.
  let rim = clamp((1.0 - wide) * 2.0, 0.0, 1.0) * shape;

  // The film on the rubber: uneven, with pinholes where it beaded.
  let mottle = tiledNoise(px / 5.0 + params.seed * 3.1, 1024.0);
  let pinhole = smoothstep(0.84, 0.93, tiledNoise(px / 1.6 + params.seed * 7.3, 1024.0));
  let film = params.load * (0.75 + 0.5 * mottle) * (1.0 - pinhole * (1.0 - rim) * 0.85);

  // The paper's tooth: a light press reaches only its high points.
  let grain = tiledNoise(px * 0.9 + params.seed * 1.7, 1024.0);
  let height = clamp(fiber.r * 0.55 + grain * 0.45, 0.0, 1.0);
  let depth = force * (film + rim * 0.35);
  let inked = smoothstep(1.0 - depth - 0.12, 1.0 - depth + 0.06, height);

  let wet = 1.0 - smoothstep(0.0, DRY_MS, params.time - LIFT_MS);
  let amount = shape * inked * (0.78 + 0.16 * film + 0.25 * rim) * (1.0 + 0.2 * wet);

  var color: vec3f;
  if (params.dark > 0.5) {
    // Only opaque ink shows on a dark sheet: it covers like gouache.
    color = mix(params.paper, params.ink, clamp(amount * 0.9, 0.0, 1.0));
  } else {
    color = kmReflectance(kmAbsorption(params.paper) + kmAbsorption(params.ink) * amount * 0.9);
  }

  // A glint off the fresh film, lit from the upper left.
  let slope = vec2f(dpdx(amount), dpdy(amount)) * 3.0;
  let normal = normalize(vec3f(-slope, 1.0));
  let glint = pow(max(dot(normal, normalize(vec3f(-0.45, -0.55, 1.0))), 0.0), 40.0);
  color += vec3f(glint * wet * amount * 0.08);

  // Solve for the least opaque pixel that lands on `color` over this page.
  let wanted = toSrgb(color);
  let page = toSrgb(params.paper);
  let change = abs(wanted - page);
  let alpha = clamp(max(max(change.r, change.g), change.b) * 4.0, 0.0, 1.0);
  if (alpha <= 0.002) {
    return vec4f(0.0);
  }
  return vec4f(clamp(wanted - page * (1.0 - alpha), vec3f(0.0), vec3f(alpha)), alpha);
}

