  private readonly fiberOffset = [Math.random(), Math.random()];
  private paper: Rgb = [0.98, 0.96, 0.9];
  private ink: Rgb = [0.85, 0.25, 0.15];
  private dark = false;
  private contact = 0;
  private pressed = false;
  private dead = false;
  private heavy: [number, number] = [1, 0];
  private lean = 0.4;
  private load = 1;
  private seed: [number, number] = [0, 0];
  onSleep: (() => void) | null = null;
  /** Called if the GPU goes away and the print with it. */
  onLost: (() => void) | null = null;

  constructor(
    private readonly engine: InkEngine,
    readonly canvas: HTMLCanvasElement,
    die: HTMLCanvasElement,
    box: { width: number; height: number; pad: number },
  ) {
    const device = engine.device;
    this.ratio = inkPixelRatio();
    this.size = [box.width + box.pad * 2, box.height + box.pad * 2];
    canvas.width = Math.max(1, Math.round(this.size[0] * this.ratio));
    canvas.height = Math.max(1, Math.round(this.size[1] * this.ratio));
    const context = canvas.getContext("webgpu");
    if (!context) throw new Error("Canvas has no WebGPU context");
    context.configure({
      device,
      format: engine.format,
      alphaMode: "premultiplied",
    });
    this.context = context;
    this.die = device.createTexture({
      label: "stamp die",
      size: [die.width, die.height],
      format: "rgba8unorm",
      usage:
        GPUTextureUsage.TEXTURE_BINDING |
        GPUTextureUsage.COPY_DST |
        GPUTextureUsage.RENDER_ATTACHMENT,
    });
    device.queue.copyExternalImageToTexture({ source: die }, { texture: this.die }, [
      die.width,
      die.height,
    ]);
    this.params = device.createBuffer({
      size: 80,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });
    this.group = device.createBindGroup({
      layout: engine.stampPipeline.getBindGroupLayout(0),
      entries: [
        { binding: 0, resource: this.die.createView() },
        { binding: 1, resource: engine.fieldSampler },
        { binding: 2, resource: engine.fibers.createView() },
        { binding: 3, resource: engine.fiberSampler },
        { binding: 4, resource: { buffer: this.params } },
      ],
    });
  }

  setColors(colors: InkColors): void {
    this.paper = colors.paper;
    this.ink = colors.ink;
    this.dark = relativeLuminance(colors.paper) < 0.3;
  }

  /**
   * The die meets the page at `contactAt` (the `performance.now()` clock).
   * Every press leans its own way and carries its own ink, so no two
   * prints match.
   */
  press(contactAt = performance.now()): void {
    if (this.dead) return;
    const angle = Math.random() * Math.PI * 2;
    this.heavy = [Math.cos(angle), Math.sin(angle)];
    this.lean = 0.2 + Math.random() * 0.5;
    this.load = 0.85 + Math.random() * 0.3;
    this.seed = [Math.random() * 100, Math.random() * 100];
    this.contact = contactAt;
    this.pressed = true;
    this.engine.wake(this);
  }

  destroy(): void {
    if (this.dead) return;
    this.dead = true;
    this.engine.forget(this);
    this.die.destroy();
    this.params.destroy();
    try {
      this.context.unconfigure();
    } catch {
      // Already gone with the device.
    }
  }

  /** @internal */
  markLost(): void {
    this.dead = true;
    this.onLost?.();
  }

  /** @internal */
  render(
    encoder: GPUCommandEncoder,
    now: number,
    timestamps: GPUQuerySet | null,
  ): void {
    if (this.dead) return;
    const raw = new Float32Array(20);
    raw.set(this.paper.map(srgbToLinear), 0);
    raw[3] = this.dark ? 1 : 0;
    raw.set(this.ink.map(srgbToLinear), 4);
    raw[7] = now - this.contact;
    raw.set(this.heavy, 8);
    raw[10] = this.lean;
    raw[11] = this.load;
    raw.set(this.size, 12);
    raw.set(this.seed, 14);
    raw.set(this.fiberOffset, 16);
    raw[18] = this.ratio;
    this.engine.device.queue.writeBuffer(this.params, 0, raw);
    const pass = encoder.beginRenderPass({
      colorAttachments: [
        {
          view: this.context.getCurrentTexture().createView(),
          clearValue: { r: 0, g: 0, b: 0, a: 0 },
          loadOp: "clear",
          storeOp: "store",
        },
      ],
      timestampWrites: timestamps
        ? { querySet: timestamps, endOfPassWriteIndex: 1 }
        : undefined,
    });
    pass.setPipeline(this.engine.stampPipeline);
    pass.setBindGroup(0, this.group);
    pass.draw(3);
    pass.end();
  }

  /** @internal */
  asleep(now: number): boolean {
    return this.dead || !this.pressed || now - this.contact > STAMP_DRY_MS;
  }
}

