/**
 * A stamp's print on WebGPU, in place of its flat CSS mark. The die is the
 * mark itself: its CSS mask image (the workflow and grade stamps), or the
 * rings and words of a mark built from elements (the clean proof).
 */
import {
  backgroundBehind,
  inkEngine,
  inkPixelRatio,
  type StampPrint,
} from "./engine";
import { parseComputedRgb } from "./tuning";

/** Room around the die for ink squeezed past its edge, in CSS pixels. */
const PAD = 4;

export interface StampPrintHandle {
  /** The die meets the page at `contactAt` (the `performance.now()` clock). */
  press(contactAt: number): void;
  destroy(): void;
  /** Called if the GPU goes away and the print with it. */
  onLost: (() => void) | null;
}

/**
 * A blank print canvas over `frame`, ready to press. Null where ink is
 * unavailable, so the caller keeps its CSS mark.
 */
export async function prepareStampPrint(
  frame: HTMLElement,
  mark: HTMLElement,
): Promise<StampPrintHandle | null> {
  const engine = await inkEngine();
  const width = frame.offsetWidth;
  const height = frame.offsetHeight;
  if (!engine || !frame.isConnected || !width || !height) return null;
  const die = await stampDie(frame, mark, PAD, inkPixelRatio());
  if (!die || !frame.isConnected) return null;

  const canvas = document.createElement("canvas");
  canvas.className = "ink-stamp__print";
  Object.assign(canvas.style, {
    left: `${-PAD}px`,
    top: `${-PAD}px`,
    width: `${width + PAD * 2}px`,
    height: `${height + PAD * 2}px`,
  });
  let print: StampPrint;
  try {
    print = engine.print(canvas, die, { width, height, pad: PAD });
  } catch {
    return null;
  }
  print.setColors({
    paper: backgroundBehind(frame),
    ink: parseComputedRgb(getComputedStyle(mark).color) ?? [0.85, 0.25, 0.15],
  });
  frame.appendChild(canvas);
  const handle: StampPrintHandle = {
    press: (at) => print.press(at),
    destroy: () => {
      print.destroy();
      canvas.remove();
    },
    onLost: null,
  };
  print.onLost = () => {
    canvas.remove();
    handle.onLost?.();
  };
  return handle;
}

/**
 * The raised face of the die, rasterised to match the print canvas:
 * `frame`'s box plus `pad` each side, at `ratio` device pixels per CSS
 * pixel. Only alpha matters. Layout offsets are used throughout, so the
 * die ignores the stamp's tilt; the canvas inherits it instead.
 */
async function stampDie(
  frame: HTMLElement,
  mark: HTMLElement,
  pad: number,
  ratio: number,
): Promise<HTMLCanvasElement | null> {
  const canvas = document.createElement("canvas");
  canvas.width = Math.round((frame.offsetWidth + pad * 2) * ratio);
  canvas.height = Math.round((frame.offsetHeight + pad * 2) * ratio);
  const ctx = canvas.getContext("2d");
  if (!ctx) return null;
  ctx.scale(ratio, ratio);
  ctx.translate(pad, pad);

  const style = getComputedStyle(mark);
  const mask =
    style.maskImage || style.getPropertyValue("-webkit-mask-image") || "";
  const url = /url\(["']?(.*?)["']?\)/.exec(mask)?.[1];
  if (url) {
    const image = new Image();
    image.src = url;
    try {
      await image.decode();
    } catch {
      return null;
    }
    // The stamp masks are all `center / contain`.
    const { x, y } = offsetWithin(mark, frame);
    const w = mark.offsetWidth;
    const h = mark.offsetHeight;
    const scale = Math.min(w / image.naturalWidth, h / image.naturalHeight);
    const iw = image.naturalWidth * scale;
    const ih = image.naturalHeight * scale;
    ctx.drawImage(image, x + (w - iw) / 2, y + (h - ih) / 2, iw, ih);
  } else {
    await document.fonts.ready;
    drawMark(ctx, mark, frame);
  }
  return canvas;
}

/**
 * Borders, outlines and single lines of words: all a stamp's mark is made
 * of. Anything fancier belongs in a mask image.
 */
function drawMark(
  ctx: CanvasRenderingContext2D,
  el: HTMLElement,
  frame: HTMLElement,
): void {
  const style = getComputedStyle(el);
  const { x, y } = offsetWithin(el, frame);
  const w = el.offsetWidth;
  const h = el.offsetHeight;
  const radius = style.borderTopLeftRadius;
  const ring = (inset: number, line: number) => {
    ctx.lineWidth = line;
    ctx.beginPath();
    if (radius === "50%") {
      ctx.ellipse(
        x + w / 2,
        y + h / 2,
        Math.max(0, w / 2 - inset),
        Math.max(0, h / 2 - inset),
        0,
        0,
        Math.PI * 2,
      );
    } else {
      ctx.roundRect(
        x + inset,
        y + inset,
        w - inset * 2,
        h - inset * 2,
        Math.max(0, (parseFloat(radius) || 0) - inset),
      );
    }
    ctx.stroke();
  };
  const border = parseFloat(style.borderTopWidth) || 0;
  if (border > 0 && style.borderTopStyle !== "none") ring(border / 2, border);
  const outline = parseFloat(style.outlineWidth) || 0;
  if (outline > 0 && style.outlineStyle !== "none") {
    ring(-(parseFloat(style.outlineOffset) || 0) - outline / 2, outline);
  }

  for (const node of el.childNodes) {
    if (node instanceof HTMLElement) {
      drawMark(ctx, node, frame);
      continue;
    }
    const text = node.nodeType === Node.TEXT_NODE ? node.textContent?.trim() : "";
    if (!text) continue;
    const words = style.textTransform === "uppercase" ? text.toUpperCase() : text;
    ctx.font = `${style.fontStyle} ${style.fontWeight} ${style.fontSize} ${style.fontFamily}`;
    ctx.letterSpacing =
      style.letterSpacing === "normal" ? "0px" : style.letterSpacing;
    ctx.textAlign =
      style.textAlign === "center"
        ? "center"
        : style.textAlign === "right" || style.textAlign === "end"
          ? "right"
          : "left";
    const left =
      ctx.textAlign === "center" ? x + w / 2 : ctx.textAlign === "right" ? x + w : x;
    // CSS centres the font's ascent and descent in the line box.
    const m = ctx.measureText(words);
    const ascent = m.fontBoundingBoxAscent;
    const descent = m.fontBoundingBoxDescent;
    ctx.fillText(words, left, y + (h - ascent - descent) / 2 + ascent);
  }
}

/** `el`'s border box relative to `frame`'s, ignoring transforms. */
function offsetWithin(
  el: HTMLElement,
  frame: HTMLElement,
): { x: number; y: number } {
  const page = (node: HTMLElement) => {
    let x = 0;
    let y = 0;
    for (let n: Element | null = node; n instanceof HTMLElement; n = n.offsetParent) {
      x += n.offsetLeft;
      y += n.offsetTop;
      // Offsets are measured from the parent's padding edge.
      if (n.offsetParent instanceof HTMLElement) {
        x += n.offsetParent.clientLeft;
        y += n.offsetParent.clientTop;
      }
    }
    return { x, y };
  };
  const a = page(el);
  const b = page(frame);
  return { x: a.x - b.x, y: a.y - b.y };
}

import {
  component$,
  Slot,
  useSignal,
  useVisibleTask$,
} from "@qwik.dev/core";
import { prepareStampPrint } from "../../utils/ink/stamp";

/** Where the die meets the paper in `stamp-die-press`. */
const CONTACT = 0.32;
/** How long a press waits for its print before going ahead without it. */
const PRINT_WAIT_MS = 400;

/**
 * A real wooden die presses the projected impression into the paper.
 * The mark is readable before the optional image loads, and remains if it fails.
 * With ink, the die leaves a print instead: pressed, not pasted, and never
 * the same twice.
 * Mount/key this component only for a new event, never for routine repaints.
 */
export const StampPress = component$<{ animated?: boolean; ink?: boolean }>(
  (props) => {
    const toolReady = useSignal(false);
    const printReady = useSignal(!props.animated || props.ink === false);
    const printed = useSignal(false);
    const frame = useSignal<HTMLElement>();

    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(async ({ cleanup }) => {
      if (printReady.value) return;
      let gone = false;
      let destroy: (() => void) | null = null;
      cleanup(() => {
        gone = true;
        destroy?.();
      });
      const giveUp = setTimeout(
        () => (printReady.value = true),
        PRINT_WAIT_MS,
      );
      const el = frame.value;
      const mark = el?.querySelector<HTMLElement>(".ink-stamp__imprint > *");
      const print = el && mark ? await prepareStampPrint(el, mark) : null;
      clearTimeout(giveUp);
      // Too late: the press has already gone ahead with the CSS mark.
      if (!el || !print || gone || printReady.value) {
        print?.destroy();
        printReady.value = true;
        return;
      }
      destroy = print.destroy;
      print.onLost = () => (printed.value = false);
      const tool = el.querySelector<HTMLImageElement>(".ink-stamp__tool");
      tool?.addEventListener("animationstart", async (e) => {
        const press = tool
          .getAnimations()
          .find((a) => (a as CSSAnimation).animationName === e.animationName);
        if (!press) return;
        await press.ready;
        const duration = Number(press.effect?.getComputedTiming().duration);
        print.press(Number(press.startTime) + duration * CONTACT);
      });
      printed.value = true;
      printReady.value = true;
    });

    return (
      <span
        ref={frame}
        class={[
          "ink-stamp",
          {
            "ink-stamp--pressing":
              props.animated && toolReady.value && printReady.value,
            "ink-stamp--printed": printed.value,
          },
        ]}
        aria-hidden="true"
      >
        <span class="ink-stamp__imprint">
          <Slot />
        </span>
        {props.animated && (
          <>
            <span class="ink-stamp__contact-shadow" />
            <img
              class="ink-stamp__tool"
              src="/assets/stamp-press/walnut-stamp.avif"
              width={768}
              height={768}
              alt=""
              draggable={false}
              onLoad$={() => (toolReady.value = true)}
            />
          </>
        )}
      </span>
    );
  },
);

