/** Client rects of a DOM range, line by line, without zero-width slivers. */
export function lineRects(range: Range): DOMRect[] {
  return [...range.getClientRects()].filter((r) => r.width > 1 && r.height > 1);
}

/**
 * A canvas positioned in `host` over the given client rects, padded so ink
 * has room to spread. Rects come back relative to the canvas.
 */
async function momentSurface(
  host: HTMLElement,
  clientRects: Box[],
  preset: InkPreset,
  layer: "over" | "under",
): Promise<{ surface: InkSurface; rects: Box[] } | null> {
  if (!clientRects.length) return null;
  const engine = await inkEngine();
  if (!engine || !host.isConnected) return null;
  const hostBox = host.getBoundingClientRect();
  const union = unionOf(clientRects);
  const left = union.x - hostBox.left - host.clientLeft + host.scrollLeft - PAD;
  const top = union.y - hostBox.top - host.clientTop + host.scrollTop - PAD;
  const width = union.width + PAD * 2;
  const height = union.height + PAD * 2;

  const canvas = document.createElement("canvas");
  canvas.className = `ink-moment ink-moment--${layer}`;
  canvas.setAttribute("aria-hidden", "true");
  Object.assign(canvas.style, {
    left: `${left}px`,
    top: `${top}px`,
    width: `${width}px`,
    height: `${height}px`,
  });
  // Beneath: first in the host, so later positioned content (the stamp
  // and its die) paints over it.
  if (layer === "under") host.prepend(canvas);
  else host.appendChild(canvas);
  const surface = engine.surface(canvas, preset);
  surface.resize(width, height);
  surface.onSleep = () => {
    surface.destroy();
    canvas.remove();
